def _draw_mini_animal_on(canvas, cx, cy, kind, s=11):
    """Мини-иконка зверя (лиса, орёл, манул) на произвольном Canvas."""
    c = canvas
    if kind == "fox":
        c.create_oval(cx - s, cy - s * 0.6, cx + s, cy + s, fill="#ef8236", outline="#b4541a", width=1)
        c.create_polygon(cx - s, cy - s * 0.5, cx - s * 0.6, cy - s * 1.6, cx - s * 0.1, cy - s * 0.7,
                         fill="#ef8236", outline="#b4541a", width=1)
        c.create_polygon(cx + s, cy - s * 0.5, cx + s * 0.6, cy - s * 1.6, cx + s * 0.1, cy - s * 0.7,
                         fill="#ef8236", outline="#b4541a", width=1)
        c.create_polygon(cx - s * 0.6, cy + s * 0.1, cx, cy + s * 0.9, cx + s * 0.6, cy + s * 0.1,
                         fill="#fdf6ec", outline="")
        c.create_oval(cx - s * 0.45, cy - s * 0.35, cx - s * 0.2, cy - s * 0.1, fill="#2b2320", outline="")
        c.create_oval(cx + s * 0.2, cy - s * 0.35, cx + s * 0.45, cy - s * 0.1, fill="#2b2320", outline="")
    elif kind == "eagle":
        c.create_polygon(cx - s * 1.5, cy - s * 0.2, cx - s * 0.3, cy - s * 1.1, cx, cy - s * 0.2,
                         cx + s * 0.3, cy - s * 1.1, cx + s * 1.5, cy - s * 0.2,
                         cx + s * 0.5, cy + s * 0.2, cx - s * 0.5, cy + s * 0.2,
                         fill="#5b4632", outline="#3a2d20", width=1)
        c.create_oval(cx - s * 0.45, cy - s * 0.85, cx + s * 0.45, cy + s * 0.15, fill="#f3ece0", outline="#c9b9a0")
        c.create_polygon(cx + s * 0.3, cy - s * 0.6, cx + s * 0.95, cy - s * 0.35, cx + s * 0.3, cy - s * 0.15,
                         fill="#f2b134", outline="")
        c.create_oval(cx + s * 0.05, cy - s * 0.65, cx + s * 0.22, cy - s * 0.48, fill="#241d18", outline="")
    else:  # manul
        c.create_oval(cx - s, cy - s * 0.6, cx + s, cy + s, fill="#a8977f", outline="#6d5f4e", width=1)
        c.create_oval(cx - s * 1.1, cy - s * 1.0, cx - s * 0.5, cy - s * 0.4, fill="#a8977f", outline="#6d5f4e", width=1)
        c.create_oval(cx + s * 0.5, cy - s * 1.0, cx + s * 1.1, cy - s * 0.4, fill="#a8977f", outline="#6d5f4e", width=1)
        c.create_polygon(cx - s * 0.5, cy - s * 0.25, cx - s * 0.2, cy - s * 0.45, cx - s * 0.2, cy - s * 0.05,
                         fill="#e8dfd0", outline="")
        c.create_polygon(cx + s * 0.5, cy - s * 0.25, cx + s * 0.2, cy - s * 0.45, cx + s * 0.2, cy - s * 0.05,
                         fill="#e8dfd0", outline="")
        c.create_oval(cx - s * 0.35, cy - s * 0.32, cx - s * 0.15, cy - s * 0.12, fill="#c9a227", outline="")
        c.create_oval(cx + s * 0.15, cy - s * 0.32, cx + s * 0.35, cy - s * 0.12, fill="#c9a227", outline="")
        c.create_polygon(cx - s * 0.15, cy + s * 0.25, cx + s * 0.15, cy + s * 0.25, cx, cy + s * 0.5,
                         fill="#4d4038", outline="")


def _tk_font(w, size=None, scale=0.75):
    """Шрифт Tk для виджета модели: семейство + размер + жирный/курсив."""
    family = ANDROID_TO_TK_FONT.get(str(w.get("font", "sans-serif")), "Segoe UI")
    if size is None:
        try:
            size = max(8, int(float(w.get("textSize", 15)) * scale))
        except (TypeError, ValueError):
            size = 11
    style = " ".join(p for p in ("bold" if w.get("bold") else "", "italic" if w.get("italic") else "") if p)
    return (family, size, style or "normal")


def _pil_font_path(w):
    """Файл TrueType под выбранный шрифт и начертание (для повёрнутых кнопок)."""
    files = PIL_FONT_FILES.get(str(w.get("font", "sans-serif")), PIL_FONT_FILES["sans-serif"])
    idx = (1 if w.get("bold") else 0) + (2 if w.get("italic") else 0)
    return files[idx]


def _has_text(w):
    return w.get("tag") in TEXT_WIDGET_TAGS


