COURSE_DEVICES = [
    ("tachometer", "📈 Тахометр", "Измерение оборотов двигателя и вывод показаний на экран телефона."),
    ("alarm", "⏰ Умный будильник", "Настройка будильника с телефона и управление светом/звуком по Bluetooth."),
    ("rgb", "💡 RGB-ночник", "Выбор цвета и яркости подсветки с телефона через Bluetooth-модуль."),
]


class CodeEditorWithSwatches(tk.Frame):
    def __init__(self, parent, bg="#1e1f22", fg="#bcbec4", on_change=None):
        super().__init__(parent, bg=bg)
        self.on_change = on_change

        self.gutter = tk.Canvas(self, width=54, bg="#2b2d30", highlightthickness=0)
        self.gutter.pack(side=tk.LEFT, fill=tk.Y)

        self.text = tk.Text(
            self, font=("Consolas", 11), bg=bg, fg=fg,
            insertbackground="white", undo=True, wrap=tk.NONE,
            padx=8, pady=5, borderwidth=0, highlightthickness=0,
            selectbackground="#214283"
        )
        self.v_scroll = ttk.Scrollbar(self, orient=tk.VERTICAL, command=self._on_vscroll)
        self.h_scroll = ttk.Scrollbar(self, orient=tk.HORIZONTAL, command=self.text.xview)

        self.text.configure(yscrollcommand=self._on_text_scroll, xscrollcommand=self.h_scroll.set)

        self.v_scroll.pack(side=tk.RIGHT, fill=tk.Y)
        self.h_scroll.pack(side=tk.BOTTOM, fill=tk.X)
        self.text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        self.text.bind("<KeyRelease>", self._on_key_release)
        self.text.bind("<MouseWheel>", lambda e: self.after(10, self.redraw_gutter))
        self.text.bind("<ButtonRelease-1>", lambda e: self.after(10, self.redraw_gutter))
        self.text.bind("<Configure>", lambda e: self.after(10, self.redraw_gutter))

    def _on_vscroll(self, *args):
        self.text.yview(*args)
        self.redraw_gutter()

    def _on_text_scroll(self, *args):
        self.v_scroll.set(*args)
        self.redraw_gutter()

    def _on_key_release(self, event=None):
        self.redraw_gutter()
        self.highlight_syntax()
        if self.on_change:
            self.on_change()

    def get_code(self):
        return self.text.get("1.0", "end-1c")

    def set_code(self, code):
        try:
            pos = self.text.index(tk.INSERT)
        except Exception:
            pos = "1.0"
        self.text.delete("1.0", tk.END)
        self.text.insert("1.0", code)
        try:
            self.text.mark_set(tk.INSERT, pos)
        except Exception:
            pass
        self.redraw_gutter()
        self.highlight_syntax()

    def highlight_syntax(self):
        for tag in ["tag", "attr", "str", "kw", "comm"]:
            self.text.tag_remove(tag, "1.0", tk.END)

        self.text.tag_configure("tag", foreground="#e8bf6a")
        self.text.tag_configure("attr", foreground="#bababa")
        self.text.tag_configure("str", foreground="#6a8759")
        self.text.tag_configure("kw", foreground="#cc7832", font=("Consolas", 11, "bold"))
        self.text.tag_configure("comm", foreground="#808080")

        code = self.get_code()

        for m in re.finditer(r'"[^"\n]*"', code):
            self.text.tag_add("str", f"1.0 + {m.start()} chars", f"1.0 + {m.end()} chars")

        for m in re.finditer(r'</?[A-Za-z0-9_.]+|\bxmlns:[a-z]+|/>|>', code):
            self.text.tag_add("tag", f"1.0 + {m.start()} chars", f"1.0 + {m.end()} chars")

        for m in re.finditer(r'\b(package|import|public|private|protected|class|interface|extends|implements|void|int|double|float|boolean|char|String|new|return|if|else|switch|case|default|break|for|while|do|try|catch|finally|static|final|this|super|Override)\b', code):
            self.text.tag_add("kw", f"1.0 + {m.start()} chars", f"1.0 + {m.end()} chars")

        for m in re.finditer(r'//[^\n]*|<!--[\s\S]*?-->', code):
            self.text.tag_add("comm", f"1.0 + {m.start()} chars", f"1.0 + {m.end()} chars")

    def redraw_gutter(self):
        self.gutter.delete("all")
        i = self.text.index("@0,0")
        while True:
            dline = self.text.dlineinfo(i)
            if dline is None:
                break
            y = dline[1]
            line_num = str(i).split(".")[0]
            self.gutter.create_text(24, y + 2, anchor="ne", text=line_num, font=("Consolas", 9), fill="#606366")

            line_text = self.text.get(f"{line_num}.0", f"{line_num}.end")
            color_matches = list(re.finditer(r'#([0-9a-fA-F]{6}|[0-9a-fA-F]{3})\b', line_text))
            if color_matches:
                hex_val = color_matches[0].group(0)
                if len(hex_val) == 4:
                    hex_val = "#" + "".join([c * 2 for c in hex_val[1:]])
                try:
                    rect_id = self.gutter.create_rectangle(
                        30, y + 3, 45, y + 17,
                        fill=hex_val, outline="#ffffff", width=1
                    )
                    self.gutter.tag_bind(
                        rect_id, "<Button-1>",
                        lambda e, ln=line_num, old_c=color_matches[0].group(0): self.pick_color(ln, old_c)
                    )
                except tk.TclError:
                    pass

            i = self.text.index(f"{i}+1line")

    def pick_color(self, line_num, old_color):
        color = colorchooser.askcolor(initialcolor=old_color, title="Выберите цвет (AS fox&eagle&manul Color Picker)")
        if color and color[1]:
            new_hex = color[1].upper()
            line_text = self.text.get(f"{line_num}.0", f"{line_num}.end")
            new_line = line_text.replace(old_color, new_hex, 1)
            self.text.delete(f"{line_num}.0", f"{line_num}.end")
            self.text.insert(f"{line_num}.0", new_line)
            self.redraw_gutter()
            self.highlight_syntax()
            if self.on_change:
                self.on_change()


