class DoomEnemy:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.hp = 4
        self.pain = 0.0
        self.cd = random.uniform(0.6, 1.6)
        self.alert = False
        self.atk = 0.0


class DoomEngine:
    PLANE = 0.66
    MOVE_SPEED = 3.0
    TURN_SPEED = 2.3

    def __init__(self):
        self.hp = 100
        self.ammo = 40
        self.kills = 0
        self.level_idx = 0
        self.state = "play"  # play / dead / win
        self.msg = ""
        self.msg_t = 0.0
        self.load_level(0)

    # ---------- служебное ----------
    def set_msg(self, text, sec=2.5):
        self.msg = text
        self.msg_t = sec

    def load_level(self, idx):
        lvl = DOOM_LEVELS[idx]
        self.level_idx = idx
        self.grid = [list(r) for r in lvl["map"]]
        self.rows = len(self.grid)
        self.cols = len(self.grid[0])
        self.enemies = []
        self.items = []
        self.door = (1.5, 1.5)
        self.px, self.py = 1.5, 1.5
        self.angle = lvl.get("angle", 0.0)
        for y in range(self.rows):
            for x in range(self.cols):
                ch = self.grid[y][x]
                if ch == "P":
                    self.px, self.py = x + 0.5, y + 0.5
                    self.grid[y][x] = "."
                elif ch == "E":
                    self.enemies.append(DoomEnemy(x + 0.5, y + 0.5))
                    self.grid[y][x] = "."
                elif ch in "HA":
                    self.items.append({"kind": ch, "x": x + 0.5, "y": y + 0.5})
                    self.grid[y][x] = "."
                elif ch == "X":
                    self.door = (x + 0.5, y + 0.5)
        self.fire_cd = 0.0
        self.flash = 0.0
        self.hurt_t = 0.0
        self.set_msg(lvl["name"], 3.0)

    def restart(self):
        idx = self.level_idx if self.state == "dead" else 0
        self.hp = 100
        self.ammo = 40
        if self.state == "win":
            self.kills = 0
        self.state = "play"
        self.load_level(idx)

    @property
    def door_open(self):
        return len(self.enemies) == 0

    def cell(self, x, y):
        if x < 0 or y < 0 or x >= self.cols or y >= self.rows:
            return "#"
        return self.grid[y][x]

    def is_wall(self, x, y):
        return self.cell(int(math.floor(x)), int(math.floor(y))) in DOOM_WALL_CHARS

    def collides(self, x, y, r=0.22):
        for cx in (x - r, x + r):
            for cy in (y - r, y + r):
                if self.is_wall(cx, cy):
                    return True
        return False

    # ---------- лучи ----------
    def cast(self, ox, oy, rdx, rdy):
        mx, my = int(math.floor(ox)), int(math.floor(oy))
        ddx = abs(1.0 / rdx) if rdx != 0 else 1e30
        ddy = abs(1.0 / rdy) if rdy != 0 else 1e30
        if rdx < 0:
            stepx, sdx = -1, (ox - mx) * ddx
        else:
            stepx, sdx = 1, (mx + 1.0 - ox) * ddx
        if rdy < 0:
            stepy, sdy = -1, (oy - my) * ddy
        else:
            stepy, sdy = 1, (my + 1.0 - oy) * ddy
        side = 0
        ch = "#"
        for _ in range(80):
            if sdx < sdy:
                sdx += ddx
                mx += stepx
                side = 0
            else:
                sdy += ddy
                my += stepy
                side = 1
            ch = self.cell(mx, my)
            if ch in DOOM_WALL_CHARS:
                break
        t = (sdx - ddx) if side == 0 else (sdy - ddy)
        wx = (oy + t * rdy) if side == 0 else (ox + t * rdx)
        wx -= math.floor(wx)
        return t, side, ch, wx

    def has_los(self, ax, ay, bx, by):
        d = math.hypot(bx - ax, by - ay)
        if d < 1e-6:
            return True
        t = self.cast(ax, ay, (bx - ax) / d, (by - ay) / d)[0]
        return t >= d - 0.05

    # ---------- стрельба ----------
    def find_target(self):
        best, best_d = None, 1e9
        for e in self.enemies:
            dx, dy = e.x - self.px, e.y - self.py
            d = math.hypot(dx, dy)
            if d < 0.2 or d >= best_d:
                continue
            diff = (math.atan2(dy, dx) - self.angle + math.pi) % (2 * math.pi) - math.pi
            if abs(diff) < math.atan2(0.35, d) and self.has_los(self.px, self.py, e.x, e.y):
                best, best_d = e, d
        return best

    def shoot(self):
        if self.state != "play" or self.fire_cd > 0:
            return False
        if self.ammo <= 0:
            if self.msg_t <= 0:
                self.set_msg("Нет патронов!", 1.0)
            return False
        self.ammo -= 1
        self.fire_cd = 0.38
        self.flash = 0.08
        target = self.find_target()
        if target:
            target.hp -= random.randint(1, 3)
            target.pain = 0.25
            target.alert = True
            if target.hp <= 0:
                self.enemies.remove(target)
                self.kills += 1
                if not self.enemies:
                    self.set_msg("Все демоны уничтожены! Идите к зелёной двери", 3.0)
        return True

    def hurt(self, dmg):
        self.hp -= dmg
        self.hurt_t = 0.25
        if self.hp <= 0:
            self.hp = 0
            self.state = "dead"

    # ---------- обновление ----------
    def update(self, dt, inp):
        self.msg_t = max(0.0, self.msg_t - dt)
        self.fire_cd = max(0.0, self.fire_cd - dt)
        self.flash = max(0.0, self.flash - dt)
        self.hurt_t = max(0.0, self.hurt_t - dt)
        if self.state != "play":
            return

        fwd = inp.get("fwd", 0)
        strafe = inp.get("strafe", 0)
        turn = inp.get("turn", 0)
        self.angle += turn * self.TURN_SPEED * dt
        ca, sa = math.cos(self.angle), math.sin(self.angle)
        vx = ca * fwd - sa * strafe
        vy = sa * fwd + ca * strafe
        n = math.hypot(vx, vy)
        if n > 1:
            vx, vy = vx / n, vy / n
        nx = self.px + vx * self.MOVE_SPEED * dt
        if not self.collides(nx, self.py):
            self.px = nx
        ny = self.py + vy * self.MOVE_SPEED * dt
        if not self.collides(self.px, ny):
            self.py = ny

        if inp.get("fire"):
            self.shoot()

        self._update_enemies(dt)
        self._pickups()
        self._check_exit()

    def _update_enemies(self, dt):
        for e in self.enemies:
            dx, dy = self.px - e.x, self.py - e.y
            d = math.hypot(dx, dy)
            e.pain = max(0.0, e.pain - dt)
            e.cd = max(0.0, e.cd - dt)
            e.atk = max(0.0, e.atk - dt)
            seen = d < 12 and self.has_los(e.x, e.y, self.px, self.py)
            if seen:
                e.alert = True
            if not e.alert or e.pain > 0:
                continue
            if d > 1.2:
                sx, sy = dx / d * 1.1 * dt, dy / d * 1.1 * dt
                if not self.collides(e.x + sx, e.y, 0.3):
                    e.x += sx
                if not self.collides(e.x, e.y + sy, 0.3):
                    e.y += sy
            if seen and e.cd <= 0 and d < 8:
                e.cd = random.uniform(1.4, 2.4)
                e.atk = 0.25
                if d < 1.6 or random.random() < 0.55:
                    self.hurt(random.randint(4, 9))
                    if self.state != "play":
                        return

    def _pickups(self):
        for it in list(self.items):
            if math.hypot(it["x"] - self.px, it["y"] - self.py) < 0.55:
                if it["kind"] == "H":
                    if self.hp >= 100:
                        continue
                    self.hp = min(100, self.hp + 25)
                    self.set_msg("+25 здоровья", 1.2)
                else:
                    self.ammo += 15
                    self.set_msg("+15 патронов", 1.2)
                self.items.remove(it)

    def _check_exit(self):
        if math.hypot(self.door[0] - self.px, self.door[1] - self.py) < 1.3:
            if self.door_open:
                if self.level_idx + 1 >= len(DOOM_LEVELS):
                    self.state = "win"
                else:
                    self.hp = min(100, self.hp + 25)
                    self.ammo += 15
                    self.load_level(self.level_idx + 1)
            elif self.msg_t <= 0:
                self.set_msg("Дверь заперта: убейте всех демонов!", 1.5)


def _doom_enemy_strips(u, pain, atk):
    body = (139, 58, 43)
    head = (181, 83, 60)
    if pain > 0:
        body, head = (240, 200, 190), (255, 230, 220)
    out = []
    if 0.15 <= u <= 0.85:
        out.append((0.38, 1.0, body))
    if 0.04 <= u < 0.15 or 0.85 < u <= 0.96:
        out.append((0.42, 0.78, head))
    if 0.2 <= u < 0.45 or 0.55 < u <= 0.8:
        out.append((0.85, 1.0, (70, 30, 25)))
    if 0.3 <= u <= 0.7:
        out.append((0.12, 0.42, head))
    if 0.27 <= u < 0.36 or 0.64 < u <= 0.73:
        out.append((0.0, 0.16, (232, 224, 192)))
    eyes = (255, 40, 40) if atk > 0 else (255, 224, 0)
    if 0.38 <= u < 0.47 or 0.53 < u <= 0.62:
        out.append((0.2, 0.27, eyes))
    if 0.43 <= u <= 0.57:
        out.append((0.32, 0.37, (20, 0, 0)))
    return out


def _doom_item_strips(u, kind):
    out = []
    if kind == "H":
        if 0.25 <= u <= 0.75:
            out.append((0.55, 1.0, (235, 235, 235)))
        if 0.45 <= u <= 0.55:
            out.append((0.6, 0.95, (200, 20, 20)))
        if 0.3 <= u <= 0.7:
            out.append((0.7, 0.82, (200, 20, 20)))
    else:
        if 0.2 <= u <= 0.8:
            out.append((0.6, 1.0, (200, 160, 30)))
            out.append((0.75, 0.85, (90, 60, 10)))
    return out


class DoomRenderer:
    BUTTONS = {
        "fwd": (90, 468, 30, "▲"),
        "back": (90, 572, 30, "▼"),
        "left": (36, 520, 30, "◀"),
        "right": (144, 520, 30, "▶"),
        "fire": (280, 525, 58, "🔥"),
    }
    AUTO_RECT = (225, 418, 335, 448)

    def __init__(self, canvas, engine):
        self.c = canvas
        self.e = engine
        self.W = DOOM_VIEW_W
        self.VH = DOOM_VIEW_H
        self.N = DOOM_RAYS
        self.cw = self.W / self.N
        self._color_cache = {}
        self._level_seen = None
        self.zbuf = [0.0] * self.N
        c = canvas
        c.configure(bg="#000000")

        nb = 10
        half = self.VH / 2
        self.ceil_bands, self.floor_bands = [], []
        for i in range(nb):
            y0 = half / nb * i
            self.ceil_bands.append(c.create_rectangle(0, y0, self.W, y0 + half / nb + 1, fill="#000000", outline=""))
            self.floor_bands.append(c.create_rectangle(0, half + y0, self.W, half + y0 + half / nb + 1, fill="#000000", outline=""))
        self.cols = [c.create_rectangle(0, 0, 0, 0, fill="#000000", outline="") for _ in range(self.N)]

        # Оружие
        cx = self.W / 2
        self.gun_flash = c.create_polygon(cx - 16, self.VH - 100, cx, self.VH - 140, cx + 16, self.VH - 100, cx, self.VH - 90,
                                          fill="#ffcc33", outline="#ff7700", width=2, tags="hud", state="hidden")
        self.gun_barrel = c.create_rectangle(cx - 9, self.VH - 100, cx + 9, self.VH - 40, fill="#555a62", outline="#222", width=2, tags="hud")
        self.gun_body = c.create_polygon(cx - 38, self.VH - 26, cx - 22, self.VH - 62, cx + 22, self.VH - 62, cx + 38, self.VH - 26,
                                         fill="#3b3f46", outline="#222", width=2, tags="hud")
        # Прицел
        c.create_line(cx - 7, self.VH / 2, cx + 7, self.VH / 2, fill="#ffffff", tags="hud")
        c.create_line(cx, self.VH / 2 - 7, cx, self.VH / 2 + 7, fill="#ffffff", tags="hud")
        # Эффект урона
        self.hurt_overlay = c.create_rectangle(0, 0, self.W, self.VH, fill="#cc0000", stipple="gray50", outline="", tags="hud", state="hidden")
        # HUD
        c.create_rectangle(0, self.VH - 26, self.W, self.VH, fill="#101216", outline="", tags="hud")
        self.hud_hp = c.create_text(8, self.VH - 13, anchor="w", fill="#ff5a5a", font=("Consolas", 12, "bold"), text="", tags="hud")
        self.hud_ammo = c.create_text(self.W / 2, self.VH - 13, fill="#ffd54f", font=("Consolas", 12, "bold"), text="", tags="hud")
        self.hud_en = c.create_text(self.W - 8, self.VH - 13, anchor="e", fill="#80cbc4", font=("Consolas", 12, "bold"), text="", tags="hud")
        self.hud_level = c.create_text(8, 10, anchor="w", fill="#e0e0e0", font=("Segoe UI", 8, "bold"), text="", tags="hud")
        self.msg_item = c.create_text(self.W / 2, 70, fill="#ffffff", font=("Segoe UI", 11, "bold"), text="", tags="hud")
        # Оверлей конца игры
        self.over_bg = c.create_rectangle(0, 0, self.W, self.VH, fill="#000000", stipple="gray50", outline="", tags="hud", state="hidden")
        self.over_title = c.create_text(self.W / 2, self.VH / 2 - 20, fill="#ff3b3b", font=("Impact", 28, "bold"), text="", tags="hud")
        self.over_sub = c.create_text(self.W / 2, self.VH / 2 + 25, fill="#ffffff", font=("Segoe UI", 10), text="", tags="hud")

        self._build_controls()

    # ---------- элементы управления ----------
    def _build_controls(self):
        c = self.c
        c.create_rectangle(0, self.VH, self.W, DOOM_CANVAS_H, fill="#15171a", outline="")
        self.btn_items = {}
        for name, (x, y, r, label) in self.BUTTONS.items():
            fill = "#8b1a1a" if name == "fire" else "#2b2f36"
            oid = c.create_oval(x - r, y - r, x + r, y + r, fill=fill, outline="#555a62", width=2)
            c.create_text(x, y, text=label, fill="#ffffff", font=("Segoe UI", 22 if name == "fire" else 16, "bold"))
            self.btn_items[name] = oid
        x1, y1, x2, y2 = self.AUTO_RECT
        self.auto_rect = c.create_rectangle(x1, y1, x2, y2, fill="#2b2f36", outline="#555a62", width=2)
        self.auto_text = c.create_text((x1 + x2) / 2, (y1 + y2) / 2, text="", fill="#ffffff", font=("Segoe UI", 9, "bold"))
        c.create_text(10, 420, anchor="w", fill="#7d8590", font=("Segoe UI", 8),
                      text="WASD/стрелки • Q/E — шаг вбок\nПробел — огонь • R — рестарт")
        c.create_text(self.W / 2, 625, fill="#555a62", font=("Segoe UI", 8),
                      text="Свайп по экрану — поворот • тап — выстрел")

    def hit_button(self, x, y):
        for name, (bx, by, r, _) in self.BUTTONS.items():
            if (x - bx) ** 2 + (y - by) ** 2 <= (r + 6) ** 2:
                return name
        return None

    def hit_auto(self, x, y):
        x1, y1, x2, y2 = self.AUTO_RECT
        return x1 <= x <= x2 and y1 <= y <= y2

    # ---------- цвета ----------
    def _hex(self, rgb, f):
        key = (rgb, int(f * 32))
        col = self._color_cache.get(key)
        if col is None:
            f = int(f * 32) / 32.0
            col = "#%02x%02x%02x" % (min(255, int(rgb[0] * f)), min(255, int(rgb[1] * f)), min(255, int(rgb[2] * f)))
            self._color_cache[key] = col
        return col

    def _set_level_visuals(self):
        lvl = DOOM_LEVELS[self.e.level_idx]
        nb = len(self.ceil_bands)
        for i in range(nb):
            self.c.itemconfig(self.ceil_bands[i], fill=self._hex(lvl["ceil"], 0.35 + 0.65 * (i + 1) / nb))
            self.c.itemconfig(self.floor_bands[i], fill=self._hex(lvl["floor"], 1.0 - 0.7 * (i + 1) / nb * 0.0 - 0.6 * (1 - (i + 1) / nb)))
        # Мини-карта
        self.c.delete("mm_s")
        ms = 4
        ox = self.W - self.e.cols * ms - 6
        self.mm_origin = (ox, 6, ms)
        for y in range(self.e.rows):
            for x in range(self.e.cols):
                ch = self.e.grid[y][x]
                if ch in DOOM_WALL_CHARS:
                    col = "#2e7d32" if ch == "X" else "#8a8f98"
                    self.c.create_rectangle(ox + x * ms, 6 + y * ms, ox + (x + 1) * ms, 6 + (y + 1) * ms, fill=col, outline="", tags=("mm_s", "hud"))
        self._level_seen = self.e.level_idx

    # ---------- кадр ----------
    def render(self, pressed=(), auto_on=True):
        e, c = self.e, self.c
        if self._level_seen != e.level_idx:
            self._set_level_visuals()
        lvl = DOOM_LEVELS[e.level_idx]
        W, VH, N, cw = self.W, self.VH, self.N, self.cw

        dirx, diry = math.cos(e.angle), math.sin(e.angle)
        plx, ply = -diry * e.PLANE, dirx * e.PLANE

        # Стены
        for i in range(N):
            camx = 2.0 * (i + 0.5) / N - 1.0
            t, side, ch, wx = e.cast(e.px, e.py, dirx + plx * camx, diry + ply * camx)
            t = max(t, 0.05)
            self.zbuf[i] = t
            lh = VH / t
            y0 = max(0.0, VH / 2 - lh / 2)
            y1 = min(float(VH), VH / 2 + lh / 2)
            if ch == "X":
                base = (40, 200, 90) if e.door_open else (150, 30, 30)
            else:
                base = lvl["walls"].get(ch, (128, 128, 128))
            f = max(0.12, 1.0 - t / 11.0)
            if side == 1:
                f *= 0.72
            if (wx * 4.0) % 1.0 < 0.07:
                f *= 0.62
            c.coords(self.cols[i], i * cw, y0, (i + 1) * cw, y1)
            c.itemconfig(self.cols[i], fill=self._hex(base, f))

        # Спрайты (демоны, предметы)
        c.delete("spr")
        inv = 1.0 / (plx * diry - dirx * ply)
        sprites = []
        for en in e.enemies:
            sprites.append(("E", en, en.x, en.y))
        for it in e.items:
            sprites.append((it["kind"], it, it["x"], it["y"]))
        drawn = []
        for kind, obj, sx, sy in sprites:
            rx, ry = sx - e.px, sy - e.py
            tx = inv * (diry * rx - dirx * ry)
            ty = inv * (-ply * rx + plx * ry)
            if ty > 0.15:
                drawn.append((ty, tx, kind, obj))
        drawn.sort(key=lambda s: -s[0])
        for ty, tx, kind, obj in drawn:
            scale, aspect = (0.85, 0.75) if kind == "E" else (0.35, 0.9)
            lh = VH / ty
            bottom = VH / 2 + lh / 2
            top = bottom - lh * scale
            height = bottom - top
            half_cols = max(0.5, (height * aspect / cw) / 2)
            center = N / 2.0 * (1.0 + tx / ty)
            first = int(center - half_cols)
            last = int(center + half_cols)
            f = max(0.3, 1.0 - ty / 14.0)
            for col in range(max(0, first), min(N - 1, last) + 1):
                if ty >= self.zbuf[col]:
                    continue
                u = (col + 0.5 - (center - half_cols)) / (2 * half_cols)
                if u < 0 or u > 1:
                    continue
                if kind == "E":
                    strips = _doom_enemy_strips(u, obj.pain, obj.atk)
                else:
                    strips = _doom_item_strips(u, kind)
                for v0, v1, rgb in strips:
                    ya = max(0.0, top + v0 * height)
                    yb = min(float(VH), top + v1 * height)
                    if yb > ya:
                        c.create_rectangle(col * cw, ya, (col + 1) * cw, yb, fill=self._hex(rgb, f), outline="", tags="spr")

        # Оружие и эффекты
        c.itemconfig(self.gun_flash, state="normal" if e.flash > 0 else "hidden")
        c.itemconfig(self.hurt_overlay, state="normal" if e.hurt_t > 0 else "hidden")

        # HUD
        c.itemconfig(self.hud_hp, text=f"❤ {e.hp}")
        c.itemconfig(self.hud_ammo, text=f"🔫 {e.ammo}")
        c.itemconfig(self.hud_en, text=f"👹 {len(e.enemies)}")
        c.itemconfig(self.hud_level, text=lvl["name"])
        c.itemconfig(self.msg_item, text=e.msg if e.msg_t > 0 else "")

        # Мини-карта (динамика)
        c.delete("mm_d")
        ox, oy, ms = self.mm_origin
        for en in e.enemies:
            c.create_oval(ox + en.x * ms - 2, oy + en.y * ms - 2, ox + en.x * ms + 2, oy + en.y * ms + 2, fill="#ff3b3b", outline="", tags=("mm_d", "hud"))
        c.create_oval(ox + e.px * ms - 2, oy + e.py * ms - 2, ox + e.px * ms + 2, oy + e.py * ms + 2, fill="#66ff66", outline="", tags=("mm_d", "hud"))
        c.create_line(ox + e.px * ms, oy + e.py * ms, ox + (e.px + dirx * 1.5) * ms, oy + (e.py + diry * 1.5) * ms, fill="#66ff66", tags=("mm_d", "hud"))

        # Экран конца игры
        if e.state == "play":
            c.itemconfig(self.over_bg, state="hidden")
            c.itemconfig(self.over_title, text="")
            c.itemconfig(self.over_sub, text="")
        else:
            c.itemconfig(self.over_bg, state="normal")
            if e.state == "dead":
                c.itemconfig(self.over_title, text="ВЫ ПОГИБЛИ", fill="#ff3b3b")
            else:
                c.itemconfig(self.over_title, text="ПОБЕДА!", fill="#66ff66")
            c.itemconfig(self.over_sub, text=f"Убито демонов: {e.kills}\nТап или R — начать заново")

        c.tag_raise("hud")

        # Кнопки управления
        for name, oid in self.btn_items.items():
            on = name in pressed
            base = "#8b1a1a" if name == "fire" else "#2b2f36"
            c.itemconfig(oid, fill=("#4a90e2" if name != "fire" else "#e53935") if on else base)
        c.itemconfig(self.auto_rect, fill="#2e7d32" if auto_on else "#2b2f36")
        c.itemconfig(self.auto_text, text="АВТО-ОГОНЬ: ВКЛ" if auto_on else "АВТО-ОГОНЬ: ВЫКЛ")


class DoomMobileWindow(tk.Toplevel):
    def __init__(self, master, on_close=None):
        super().__init__(master)
        self.title("31/03/1997 — fox&eagle&manul Edition")
        self.resizable(False, False)
        self.configure(bg="#000000")
        self._on_close = on_close
        self.canvas = tk.Canvas(self, width=DOOM_VIEW_W, height=DOOM_CANVAS_H, bg="#000000", highlightthickness=0)
        self.canvas.pack()

        self.engine = DoomEngine()
        self.renderer = DoomRenderer(self.canvas, self.engine)
        self.keys = set()
        self.touch = None
        self.touch_mode = None
        self.last_x = 0
        self.drag_total = 0
        self.tap_fire = False
        self.auto_fire = True
        self._closed = False

        self.canvas.bind("<ButtonPress-1>", self._press)
        self.canvas.bind("<B1-Motion>", self._motion)
        self.canvas.bind("<ButtonRelease-1>", self._release)
        self.bind("<KeyPress>", self._key_down)
        self.bind("<KeyRelease>", self._key_up)
        self.bind("<FocusOut>", lambda e: self.keys.clear())
        self.protocol("WM_DELETE_WINDOW", self.close)

        self.focus_force()
        self._last = time.time()
        self._job = self.after(16, self._tick)

    def close(self):
        if self._closed:
            return
        self._closed = True
        try:
            self.after_cancel(self._job)
        except Exception:
            pass
        if self._on_close:
            self._on_close()
        self.destroy()

    # ---------- ввод ----------
    def _key_down(self, event):
        k = event.keysym.lower()
        if k == "escape":
            self.close()
            return
        if k in ("r", "к"):
            self.engine.restart()
        self.keys.add(k)

    def _key_up(self, event):
        self.keys.discard(event.keysym.lower())

    def _press(self, event):
        self.focus_set()
        if self.engine.state != "play":
            self.engine.restart()
            return
        if event.y < DOOM_VIEW_H:
            self.touch_mode = "look"
            self.last_x = event.x
            self.drag_total = 0
            return
        if self.renderer.hit_auto(event.x, event.y):
            self.auto_fire = not self.auto_fire
            return
        self.touch_mode = "btn"
        self.touch = self.renderer.hit_button(event.x, event.y)

    def _motion(self, event):
        if self.touch_mode == "look":
            dx = event.x - self.last_x
            self.last_x = event.x
            self.drag_total += abs(dx)
            self.engine.angle += dx * 0.012
        elif self.touch_mode == "btn":
            self.touch = self.renderer.hit_button(event.x, event.y)

    def _release(self, event):
        if self.touch_mode == "look" and self.drag_total < 8:
            self.tap_fire = True
        self.touch_mode = None
        self.touch = None

    def _inputs(self):
        k = self.keys
        t = self.touch
        fwd = (1 if (k & {"w", "ц", "up"} or t == "fwd") else 0) - (1 if (k & {"s", "ы", "down"} or t == "back") else 0)
        strafe = (1 if k & {"e", "у"} else 0) - (1 if k & {"q", "й"} else 0)
        turn = (1 if (k & {"d", "в", "right"} or t == "right") else 0) - (1 if (k & {"a", "ф", "left"} or t == "left") else 0)
        fire = bool(t == "fire" or "space" in k or self.tap_fire)
        self.tap_fire = False
        if self.auto_fire and self.engine.find_target() is not None:
            fire = True
        return {"fwd": fwd, "strafe": strafe, "turn": turn, "fire": fire}

    def _pressed_names(self):
        names = set()
        if self.touch:
            names.add(self.touch)
        k = self.keys
        if k & {"w", "ц", "up"}:
            names.add("fwd")
        if k & {"s", "ы", "down"}:
            names.add("back")
        if k & {"a", "ф", "left"}:
            names.add("left")
        if k & {"d", "в", "right"}:
            names.add("right")
        if "space" in k:
            names.add("fire")
        return names

    def _tick(self):
        if self._closed:
            return
        now = time.time()
        dt = min(0.05, now - self._last)
        self._last = now
        try:
            self.engine.update(dt, self._inputs())
            self.renderer.render(self._pressed_names(), self.auto_fire)
        except tk.TclError:
            return
        self._job = self.after(16, self._tick)


class _RotCanvasProxy:
    """Прокси для Canvas: поворачивает координаты вокруг центра, чтобы заглушка-плакат рисовалась под углом."""

    def __init__(self, canvas, cx, cy, rot, tags):
        self._canvas = canvas
        self._cx = cx
        self._cy = cy
        self._tags = tags
        rad = math.radians(rot % 360.0)
        self._c = math.cos(rad)
        self._s = math.sin(rad)

    def _pt(self, x, y):
        dx = x - self._cx
        dy = y - self._cy
        return (self._cx + dx * self._c - dy * self._s, self._cy + dx * self._s + dy * self._c)

    @staticmethod
    def _flatten(coords):
        flat = []
        for v in coords:
            if isinstance(v, (tuple, list)):
                flat.extend(v)
            else:
                flat.append(v)
        return flat

    def create_rectangle(self, x1, y1, x2, y2, **kw):
        pts = [self._pt(x, y) for x, y in ((x1, y1), (x2, y1), (x2, y2), (x1, y2))]
        flat = [c for p in pts for c in p]
        return self._canvas.create_polygon(flat, **kw)

    def create_oval(self, x1, y1, x2, y2, **kw):
        cx = (x1 + x2) / 2.0
        cy = (y1 + y2) / 2.0
        ncx, ncy = self._pt(cx, cy)
        rx = abs(x2 - x1) / 2.0
        ry = abs(y2 - y1) / 2.0
        return self.create_polygon_ellipse(ncx, ncy, rx, ry, **kw)

    def create_polygon_ellipse(self, cx, cy, rx, ry, **kw):
        pts = []
        for i in range(36):
            a = 2 * math.pi * i / 36
            pts.append(self._pt(cx + rx * math.cos(a), cy + ry * math.sin(a)))
        return self._canvas.create_polygon([c for p in pts for c in p], **kw)

    def create_line(self, *coords, **kw):
        flat = self._flatten(coords)
        out = []
        for i in range(0, len(flat) - 1, 2):
            out.extend(self._pt(flat[i], flat[i + 1]))
        return self._canvas.create_line(out, **kw)

    def create_arc(self, x1, y1, x2, y2, **kw):
        return self.create_oval(x1, y1, x2, y2, **{k: v for k, v in kw.items() if k in ("fill", "outline", "width", "tags")})

    def create_text(self, x, y, **kw):
        nx, ny = self._pt(x, y)
        kw.setdefault("angle", math.degrees(math.atan2(self._s, self._c)))
        return self._canvas.create_text(nx, ny, **kw)

    def __getattr__(self, name):
        return getattr(self._canvas, name)


class SplashScreen(tk.Toplevel):
    """Заставка при запуске: лисёнок, манул и орёл, нарисованные средствами Canvas (без внешних файлов)."""

    W, H = 640, 420

    def __init__(self, master, duration_ms=3200):
        super().__init__(master)
        self.overrideredirect(True)
        self.configure(bg="#101418")
        self.attributes("-topmost", True)
        try:
            self.attributes("-alpha", 0.98)
        except tk.TclError:
            pass

        x = (self.winfo_screenwidth() - self.W) // 2
        y = (self.winfo_screenheight() - self.H) // 2 - 40
        self.geometry(f"{self.W}x{self.H}+{x}+{y}")

        self.canvas = tk.Canvas(self, width=self.W, height=self.H, bg="#101418", highlightthickness=0)
        self.canvas.pack(fill=tk.BOTH, expand=True)
        self._draw()

        self._closing = False
        self.protocol("WM_DELETE_WINDOW", self.close)
        self.canvas.bind("<Button-1>", lambda e: self.close())
        self.bind("<Escape>", lambda e: self.close())
        self.bind("<Return>", lambda e: self.close())
        self.after(duration_ms, self.close)

    # --- вспомогательные формы ---
    def _ellipse(self, cx, cy, rx, ry, **kw):
        return self.canvas.create_oval(cx - rx, cy - ry, cx + rx, cy + ry, **kw)

    def _poly(self, pts, **kw):
        return self.canvas.create_polygon([c for p in pts for c in p], smooth=False, **kw)

    def _gradient_sky(self):
        top = (0x13, 0x1a, 0x2b)
        bottom = (0x2c, 0x3a, 0x52)
        for i in range(self.H):
            t = i / float(self.H)
            r = int(top[0] + (bottom[0] - top[0]) * t)
            g = int(top[1] + (bottom[1] - top[1]) * t)
            b = int(top[2] + (bottom[2] - top[2]) * t)
            self.canvas.create_line(0, i, self.W, i, fill=f"#{r:02x}{g:02x}{b:02x}")

    def _draw(self):
        c = self.canvas
        self._gradient_sky()

        # Луна и звёзды
        self._ellipse(540, 70, 34, 34, fill="#fff4d6", outline="")
        for sx, sy, sr in ((70, 50, 2), (130, 90, 1.5), (210, 40, 2), (300, 70, 1.4),
                           (390, 45, 1.8), (455, 100, 1.4), (600, 140, 1.6), (35, 130, 1.6)):
            self._ellipse(sx, sy, sr, sr, fill="#dbe6f5", outline="")

        # Земля
        c.create_rectangle(0, 330, self.W, self.H, fill="#1d2b25", outline="")
        self._ellipse(320, 336, 340, 46, fill="#243428", outline="")

        # Название: вместо «&» — маленькие иконки лисы, орла и манула
        title_y = 96
        parts = [("AS", "#ffb74d"), ("fox", None), ("eagle", None), ("manul", "#ffb74d")]
        # вычисляем ширину, чтобы отцентровать всю строку
        tmp_font = ("Segoe UI", 22, "bold")
        widths = []
        for text, _ in parts:
            widths.append(c.create_text(-500, -500, text=text, font=tmp_font, fill="#ffb74d"))
        spans = [c.bbox(i) for i in widths]
        for i in widths:
            c.delete(i)
        text_w = sum(b[2] - b[0] for b in spans)
        icon_w = 30
        gap = 10
        total = text_w + 3 * icon_w + 3 * gap
        x = self.W / 2 - total / 2
        for idx, (text, color) in enumerate(parts):
            if text in ("AS",):
                c.create_text(x, title_y, text=text, anchor="w", fill=color, font=tmp_font)
                x += spans[idx][2] - spans[idx][0] + gap
            else:
                kind = text
                self._draw_mini_animal(x + icon_w / 2, title_y, kind)
                x += icon_w + gap
        c.create_text(self.W / 2, 400, text="клик или Esc — начать работу",
                      fill="#6c7a89", font=("Segoe UI", 8))

        self._draw_fox(150, 368)
        self._draw_manul(320, 362)
        self._draw_eagle(490, 322)

    def _draw_mini_animal(self, cx, cy, kind):
        """Мини-иконка зверя для строки заголовка (лиса, орёл, манул)."""
        _draw_mini_animal_on(self.canvas, cx, cy, kind, s=11)

    def _draw_fox(self, cx, base):
        """Лисёнок: рыжий, с белой грудкой и пушистым хвостом."""
        # хвост
        self._poly([(cx + 44, base - 30), (cx + 96, base - 62), (cx + 104, base - 40),
                    (cx + 78, base - 18), (cx + 48, base - 12)], fill="#e8772e", outline="#b4541a", width=2)
        self._poly([(cx + 92, base - 56), (cx + 104, base - 40), (cx + 90, base - 34), (cx + 84, base - 48)],
                   fill="#fdf6ec", outline="")
        # тело
        self._ellipse(cx, base - 22, 44, 30, fill="#ef8236", outline="#b4541a", width=2)
        self._ellipse(cx - 10, base - 14, 20, 18, fill="#fdf6ec", outline="")
        # лапы
        self._ellipse(cx - 26, base - 2, 13, 7, fill="#b4541a", outline="")
        self._ellipse(cx + 20, base - 2, 13, 7, fill="#b4541a", outline="")
        # уши
        self._poly([(cx - 34, base - 62), (cx - 40, base - 108), (cx - 4, base - 78)],
                   fill="#ef8236", outline="#b4541a", width=2)
        self._poly([(cx + 34, base - 62), (cx + 40, base - 108), (cx + 4, base - 78)],
                   fill="#ef8236", outline="#b4541a", width=2)
        self._poly([(cx - 31, base - 70), (cx - 34, base - 98), (cx - 12, base - 79)], fill="#3b2b26", outline="")
        self._poly([(cx + 31, base - 70), (cx + 34, base - 98), (cx + 12, base - 79)], fill="#3b2b26", outline="")
        # голова
        self._ellipse(cx, base - 62, 36, 32, fill="#f28d3d", outline="#b4541a", width=2)
        # морда
        self._poly([(cx - 24, base - 54), (cx, base - 34), (cx + 24, base - 54)],
                   fill="#fdf6ec", outline="")
        self._ellipse(cx, base - 40, 12, 9, fill="#fdf6ec", outline="")
        self._ellipse(cx, base - 46, 5, 4, fill="#2b2320", outline="")
        # глаза
        self._ellipse(cx - 13, base - 72, 6, 6, fill="#2b2320", outline="")
        self._ellipse(cx + 13, base - 72, 6, 6, fill="#2b2320", outline="")
        self._ellipse(cx - 11, base - 74, 2, 2, fill="#ffffff", outline="")
        self._ellipse(cx + 15, base - 74, 2, 2, fill="#ffffff", outline="")

    def _draw_manul(self, cx, base):
        """Манул: самый пушистый, круглые уши по бокам, суровый взгляд."""
        # хвост
        self._poly([(cx + 40, base - 26), (cx + 78, base - 20), (cx + 84, base - 4), (cx + 58, base - 6)],
                   fill="#9a8974", outline="#6d5f4e", width=2)
        # тело — пушистое, с «оборками» по краю
        self._ellipse(cx, base - 24, 48, 34, fill="#a8977f", outline="#6d5f4e", width=2)
        for i in range(7):
            ang = math.pi + math.pi * i / 6.0
            self._ellipse(cx + 46 * math.cos(ang), base - 24 + 30 * math.sin(ang), 9, 8,
                          fill="#b7a68d", outline="")
        self._ellipse(cx - 8, base - 18, 24, 20, fill="#e8dfd0", outline="")
        # лапы
        self._ellipse(cx - 28, base - 2, 14, 7, fill="#6d5f4e", outline="")
        self._ellipse(cx + 22, base - 2, 14, 7, fill="#6d5f4e", outline="")
        # уши — низкие и круглые (главный признак манула)
        self._ellipse(cx - 32, base - 78, 12, 12, fill="#a8977f", outline="#6d5f4e", width=2)
        self._ellipse(cx + 32, base - 78, 12, 12, fill="#a8977f", outline="#6d5f4e", width=2)
        self._ellipse(cx - 32, base - 78, 5, 5, fill="#c98d7a", outline="")
        self._ellipse(cx + 32, base - 78, 5, 5, fill="#c98d7a", outline="")
        # голова
        self._ellipse(cx, base - 66, 40, 34, fill="#a8977f", outline="#6d5f4e", width=2)
        # «бакенбарды»
        for side in (-1, 1):
            for k in range(3):
                self._ellipse(cx + side * (30 + k * 4), base - 62 + k * 9, 7, 6, fill="#b7a68d", outline="")
        # глаза — узкие и недовольные
        self._poly([(cx - 20, base - 74), (cx - 8, base - 78), (cx - 8, base - 70)], fill="#e8dfd0", outline="")
        self._poly([(cx + 20, base - 74), (cx + 8, base - 78), (cx + 8, base - 70)], fill="#e8dfd0", outline="")
        self._ellipse(cx - 13, base - 73, 4, 4, fill="#c9a227", outline="")
        self._ellipse(cx + 13, base - 73, 4, 4, fill="#c9a227", outline="")
        self._ellipse(cx - 13, base - 73, 1.8, 3.4, fill="#241d18", outline="")
        self._ellipse(cx + 13, base - 73, 1.8, 3.4, fill="#241d18", outline="")
        # нос и рот
        self._poly([(cx - 5, base - 58), (cx + 5, base - 58), (cx, base - 52)], fill="#4d4038", outline="")
        self.canvas.create_line(cx, base - 52, cx, base - 48, fill="#4d4038", width=1.5)

    def _draw_eagle(self, cx, base):
        """Орёл: расправленные крылья, белая голова, жёлтый клюв."""
        # крылья
        for side in (-1, 1):
            self._poly([(cx, base - 60),
                        (cx + side * 60, base - 116),
                        (cx + side * 112, base - 92),
                        (cx + side * 78, base - 74),
                        (cx + side * 96, base - 56),
                        (cx + side * 58, base - 50),
                        (cx + side * 30, base - 34)],
                       fill="#5b4632", outline="#3a2d20", width=2)
            for k in range(4):
                self.canvas.create_line(cx + side * (46 + k * 14), base - 84 + k * 7,
                                        cx + side * (76 + k * 12), base - 100 + k * 10,
                                        fill="#7a5f42", width=1.5)
        # тело
        self._ellipse(cx, base - 48, 26, 34, fill="#6d5338", outline="#3a2d20", width=2)
        self._ellipse(cx, base - 46, 14, 22, fill="#c8ae86", outline="")
        # хвост
        self._poly([(cx - 18, base - 22), (cx + 18, base - 22), (cx + 12, base + 6), (cx - 12, base + 6)],
                   fill="#4a3727", outline="#3a2d20", width=2)
        # голова
        self._ellipse(cx, base - 100, 24, 21, fill="#f3ece0", outline="#c9b9a0", width=2)
        # клюв
        self._poly([(cx + 16, base - 104), (cx + 36, base - 96), (cx + 16, base - 90)],
                   fill="#f2b134", outline="#b9811d", width=1.5)
        # глаз
        self._ellipse(cx + 9, base - 104, 4, 4, fill="#241d18", outline="")
        self._ellipse(cx + 10, base - 105, 1.4, 1.4, fill="#ffffff", outline="")
        # лапы
        self.canvas.create_line(cx - 8, base - 16, cx - 8, base - 4, fill="#f2b134", width=3)
        self.canvas.create_line(cx + 8, base - 16, cx + 8, base - 4, fill="#f2b134", width=3)

    def close(self):
        if self._closing:
            return
        self._closing = True
        try:
            self.destroy()
        except tk.TclError:
            pass


class TopicChooser(tk.Toplevel):
    """Окно выбора темы учебного проекта: 20 карточек, которые развиваются до ПР №23."""

    def __init__(self, app, on_choose):
        super().__init__(app.root)
        self.app = app
        self.on_choose = on_choose
        self.title("🎯 Выбор темы учебного проекта — ПР №1")
        self.configure(bg="#1e1f22")
        self.geometry("880x620")
        self.minsize(720, 480)
        self.transient(app.root)
        self.grab_set()

        head = tk.Frame(self, bg="#1e1f22")
        head.pack(fill=tk.X, padx=14, pady=(12, 4))
        tk.Label(head, text="🦊 Сделай свой выбор!", bg="#1e1f22", fg="#ff9800",
                 font=("Segoe UI", 16, "bold")).pack(anchor="w")
        tk.Label(
            head,
            text="Выберите одну тему. С ПР №1 по ПР №23 вы будете дополнять именно это приложение, "
                 "а на защите ПР №23 покажете готовый проект.",
            bg="#1e1f22", fg="#90caf9", font=("Segoe UI", 9), justify=tk.LEFT, wraplength=830
        ).pack(anchor="w", pady=(2, 0))

        # прокручиваемая область с карточками
        wrap = tk.Frame(self, bg="#1e1f22")
        wrap.pack(fill=tk.BOTH, expand=True, padx=10, pady=8)
        canvas = tk.Canvas(wrap, bg="#1e1f22", highlightthickness=0)
        sb = ttk.Scrollbar(wrap, orient=tk.VERTICAL, command=canvas.yview)
        canvas.configure(yscrollcommand=sb.set)
        sb.pack(side=tk.RIGHT, fill=tk.Y)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        inner = tk.Frame(canvas, bg="#1e1f22")
        canvas.create_window((0, 0), window=inner, anchor="nw", tags="inner")
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>", lambda e: canvas.itemconfigure("inner", width=e.width))
        canvas.bind_all("<MouseWheel>", lambda e: canvas.yview_scroll(int(-e.delta / 120), "units"))

        cols = 2
        for i, t in enumerate(PROJECT_TOPICS):
            card = tk.Frame(inner, bg="#2b2d30", bd=0, highlightthickness=1,
                            highlightbackground=t["accent"], highlightcolor=t["accent"])
            card.grid(row=i // cols, column=i % cols, padx=6, pady=6, sticky="nsew")
            inner.grid_columnconfigure(i % cols, weight=1)

            title_row = tk.Frame(card, bg="#2b2d30")
            title_row.pack(fill=tk.X, padx=10, pady=(8, 2))
            tk.Label(title_row, text=t["icon"], bg="#2b2d30", font=("Segoe UI", 16)).pack(side=tk.LEFT)
            tk.Label(title_row, text=t["title"], bg="#2b2d30", fg=t["accent"],
                     font=("Segoe UI", 11, "bold")).pack(side=tk.LEFT, padx=6)

            tk.Label(card, text=t["desc"], bg="#2b2d30", fg="#c9cdd4", font=("Segoe UI", 8),
                     wraplength=370, justify=tk.LEFT).pack(fill=tk.X, padx=10)
            tk.Label(card, text=f"Поля: {', '.join(t['fields'])}", bg="#2b2d30", fg="#80cbc4",
                     font=("Segoe UI", 8, "bold")).pack(fill=tk.X, padx=10, pady=(2, 0))

            is_current = (app.project_topic == t["key"])
            btn = tk.Button(
                card, text="✔ Это моя тема" if is_current else "Выбрать эту тему",
                bg="#368746" if is_current else "#3574f0", fg="white",
                font=("Segoe UI", 9, "bold"), bd=0, pady=4, cursor="hand2",
                command=lambda k=t["key"]: self._choose(k)
            )
            btn.pack(fill=tk.X, padx=10, pady=(6, 10))

        tk.Button(self, text="Отмена", bg="#4e5157", fg="white", font=("Segoe UI", 9),
                  bd=0, pady=5, command=self.destroy).pack(fill=tk.X, padx=14, pady=(0, 12))

        self.bind("<Escape>", lambda e: self.destroy())

    def _choose(self, key):
        self.destroy()
        self.on_choose(key)


class CourseDeviceChooser(tk.Toplevel):
    """Выбор цифрового устройства для курсового проекта (ПР №24–52)."""

