    def on_practical_selected(self, event=None):
        sel_title = self.pr_combo.get()
        if sel_title not in self.practicals:
            return
        code_key, desc = self.practicals[sel_title]
        pr_num = self.pr_num_from_key(code_key)
        self.current_pr_num = pr_num
        self.refresh_task_panel(pr_num)

        if code_key == "welcome":
            self.load_default_project()
        elif code_key == "movies":
            self.load_movie_catalog_project()
        else:
            self.load_individual_pr_template(code_key, sel_title, desc)
        self._history_reset()

    def _snapshot(self):
        return {
            "screen": self.current_screen,
            "xml": self.xml_editor.get_code(),
            "bg": self.root_bg,
            "widgets": copy.deepcopy(self.widgets_data),
        }

    def _history_reset(self):
        self._undo_stack = []
        self._redo_stack = []
        self._hist_last = self._snapshot()

    def _history_note(self):
        if self._hist_restoring:
            return
        snap = self._snapshot()
        last = self._hist_last
        self._hist_last = snap
        if last is None or last["screen"] != snap["screen"] or last["xml"] == snap["xml"]:
            return
        if self.drag_mode:
            if self._hist_drag_pushed:
                return
            self._hist_drag_pushed = True
        self._undo_stack.append(last)
        if len(self._undo_stack) > 200:
            self._undo_stack.pop(0)
        self._redo_stack.clear()

    def _apply_snapshot(self, snap):
        self._hist_restoring = True
        try:
            if snap["screen"] != self.current_screen and snap["screen"] in self.screens:
                self.switch_to_screen(snap["screen"])
            self.updating_from_code = True
            self.updating_from_canvas = True
            self.xml_editor.set_code(snap["xml"])
            self.updating_from_code = False
            self.updating_from_canvas = False
            self.root_bg = snap["bg"]
            self.widgets_data = copy.deepcopy(snap["widgets"])
            keep = self.selected_id if self.get_widget_by_id(self.selected_id) else None
            self.select_widget(keep)
            self.render_designer_canvas()
            self.save_current_screen_state()
            self._hist_last = self._snapshot()
        finally:
            self.updating_from_code = False
            self.updating_from_canvas = False
            self._hist_restoring = False

    def _focus_is_text_input(self):
        w = self.root.focus_get()
        return isinstance(w, (tk.Text, tk.Entry, ttk.Entry, ttk.Combobox))

    def undo_action(self, event=None):
        if self._focus_is_text_input():
            return None
        if not self._undo_stack:
            self.log("> [Отмена] Нет действий для отмены.")
            return "break"
        self._redo_stack.append(self._snapshot())
        self._apply_snapshot(self._undo_stack.pop())
        self.log("> [Отмена] Последнее действие отменено (Ctrl+Z).")
        return "break"

    def redo_action(self, event=None):
        if self._focus_is_text_input():
            return None
        if not self._redo_stack:
            self.log("> [Повтор] Нет действий для повтора.")
            return "break"
        self._undo_stack.append(self._snapshot())
        self._apply_snapshot(self._redo_stack.pop())
        self.log("> [Повтор] Действие возвращено (Ctrl+Y).")
        return "break"

