    def _clean_num(self, val_str, default_val):
        if not val_str:
            return default_val
        m = re.search(r'([0-9]+)', str(val_str))
        return int(m.group(1)) if m else default_val

    def parse_xml_to_model(self):
        xml_code = self.xml_editor.get_code()

        root_bg_match = re.search(r'<(?:AbsoluteLayout|LinearLayout|ConstraintLayout|RelativeLayout|FrameLayout)[^>]*android:background="([^"]+)"', xml_code)
        self.root_bg = root_bg_match.group(1) if root_bg_match else "#FFFFFF"

        new_widgets = []
        pattern = re.compile(r'<(TextView|Button|ImageView|EditText|Switch|ProgressBar)\b([\s\S]*?)(?:/>|></\1>)')

        idx = 1
        for m in pattern.finditer(xml_code):
            tag = m.group(1)
            attrs = m.group(2)

            def get_attr(name, default=""):
                am = re.search(rf'android:{name}="([^"]*)"', attrs)
                return am.group(1) if am else default

            raw_id = get_attr("id", f"@+id/{tag.lower()}_{idx}")
            w_id = raw_id.replace("@+id/", "").replace("@id/", "")

            text_val = get_attr("text", get_attr("hint", tag if tag not in ("ImageView", "ProgressBar") else ""))
            x_val = self._clean_num(get_attr("layout_x", ""), 40)
            y_val = self._clean_num(get_attr("layout_y", ""), 40 + idx * 60)
            w_val = self._clean_num(get_attr("layout_width", ""), 220 if tag != "ImageView" else 120)
            h_val = self._clean_num(get_attr("layout_height", ""), 45 if tag != "ImageView" else 120)
            text_size = self._clean_num(get_attr("textSize", ""), 15)

            bg_tint = get_attr("backgroundTint", "")
            bg_norm = get_attr("background", "")
            bg_color = bg_tint if bg_tint else (bg_norm if bg_norm else ("#0099FF" if tag == "Button" else ("#FFFFFF" if tag == "EditText" else "")))

            fg_color = get_attr("textColor", "#FFFFFF" if tag == "Button" else "#212121")
            src_val = get_attr("src", "@drawable/android_question")
            rot_val = self._parse_rot(get_attr("rotation", "0"))
            target_scr = get_attr("tag", "")

            # Оформление текста: жирный/курсив и базовый шрифт
            style_val = get_attr("textStyle", "").lower()
            bold_val = ("bold" in style_val)
            italic_val = ("italic" in style_val)
            font_val = get_attr("fontFamily", "sans-serif").strip() or "sans-serif"
            if font_val not in ANDROID_TO_TK_FONT:
                font_val = "sans-serif"

            new_widgets.append({
                "tag": tag,
                "id": w_id,
                "text": text_val,
                "x": x_val,
                "y": y_val,
                "w": w_val,
                "h": h_val,
                "textSize": text_size,
                "bg": bg_color,
                "fg": fg_color,
                "src": src_val,
                "rot": rot_val,
                "target_screen": target_scr,
                "checked": True,
                "bold": bold_val,
                "italic": italic_val,
                "font": font_val,
            })
            idx += 1

        self.widgets_data = new_widgets

    def sync_model_to_xml(self):
        if self.updating_from_code:
            return
        self.updating_from_canvas = True

        lines = [
            '<?xml version="1.0" encoding="utf-8"?>',
            '<AbsoluteLayout xmlns:android="http://schemas.android.com/apk/res/android"',
            '    android:id="@+id/mainLayout"',
            '    android:layout_width="match_parent"',
            '    android:layout_height="match_parent"',
            f'    android:background="{self.root_bg}">',
            ''
        ]

        for w in self.widgets_data:
            tag = w["tag"]
            lines.append(f'    <{tag}')
            lines.append(f'        android:id="@+id/{w["id"]}"')
            if tag not in ("ImageView", "ProgressBar"):
                escaped_text = w["text"].replace('"', '&quot;')
                lines.append(f'        android:text="{escaped_text}"')
                lines.append(f'        android:textSize="{w["textSize"]}sp"')
                if w["fg"]:
                    lines.append(f'        android:textColor="{w["fg"]}"')
                if w.get("bold") or w.get("italic"):
                    style_parts = [p for p in ("bold" if w.get("bold") else "", "italic" if w.get("italic") else "") if p]
                    lines.append(f'        android:textStyle="{"|".join(style_parts)}"')
                if w.get("font") and w.get("font") != "sans-serif":
                    lines.append(f'        android:fontFamily="{w["font"]}"')
                if w["bg"]:
                    attr_name = "backgroundTint" if tag == "Button" else "background"
                    lines.append(f'        android:{attr_name}="{w["bg"]}"')
            elif tag == "ImageView":
                lines.append(f'        android:src="{w["src"]}"')
                if w["bg"]:
                    lines.append(f'        android:background="{w["bg"]}"')
            if w.get("rot"):
                lines.append(f'        android:rotation="{w["rot"]}"')

            if w.get("target_screen"):
                lines.append(f'        android:tag="{w["target_screen"]}"')
            lines.append(f'        android:layout_x="{int(w["x"])}dp"')
            lines.append(f'        android:layout_y="{int(w["y"])}dp"')
            lines.append(f'        android:layout_width="{int(w["w"])}dp"')
            lines.append(f'        android:layout_height="{int(w["h"])}dp" />')
            lines.append('')

        lines.append('</AbsoluteLayout>')
        new_xml = "\n".join(lines)

        self.xml_editor.set_code(new_xml)
        self.save_current_screen_state()
        self.updating_from_canvas = False
        self._history_note()

    def on_xml_text_modified(self):
        if self.updating_from_canvas:
            return
        self.updating_from_code = True
        self.parse_xml_to_model()
        self.render_designer_canvas()
        self.updating_from_code = False
        if not self._hist_restoring:
            self._hist_last = self._snapshot()

    def _parse_rot(self, val):
        try:
            r = float(re.sub(r"[^0-9.\-]", "", str(val)) or 0) % 360
        except ValueError:
            r = 0.0
        return int(r) if abs(r - round(r)) < 1e-9 else round(r, 1)

    def _image_name(self, src):
        base = str(src).replace("\\", "/").split("/")[-1].strip().lower()
        root, ext = os.path.splitext(base)
        return root if ext in IMAGE_EXTS else base

    def _find_image_file(self, name):
        path = self.image_files.get(name)
        if path and os.path.exists(path):
            return path
        cached = self._img_path_cache.get(name)
        now = time.time()
        if cached and (cached[0] or now - cached[1] < 2.0):
            if not cached[0] or os.path.exists(cached[0]):
                return cached[0]
        found = None
        for d in (os.getcwd(), SCRIPT_DIR, os.path.join(os.getcwd(), "drawable"), os.path.join(SCRIPT_DIR, "drawable")):
            try:
                for fname in os.listdir(d):
                    root, ext = os.path.splitext(fname)
                    if root.lower() == name and ext.lower() in IMAGE_EXTS:
                        found = os.path.join(d, fname)
                        break
            except OSError:
                continue
            if found:
                break
        # Встроенная лиса-маскот генерируется программой, а не лежит в папке проекта
        if not found and name == "fox_mascot":
            fox = self._fox_mascot_file()
            if fox:
                found = fox
                self.image_files["fox_mascot"] = fox
        self._img_path_cache[name] = (found, now)
        return found

    def _load_photo(self, path, w, h, rot):
        w, h = max(1, int(w)), max(1, int(h))
        rot = self._parse_rot(rot)
        key = (path, os.path.getmtime(path), w, h, rot)
        if key in self.image_cache:
            return self.image_cache[key]
        if len(self.image_cache) > 300:
            self.image_cache.clear()
        if PIL_OK:
            im = Image.open(path)
            try:
                im = ImageOps.exif_transpose(im)
            except Exception:
                pass
            im = im.convert("RGBA")
            if rot:
                im = im.rotate(-rot, expand=True, resample=Image.BICUBIC)
            scale = min(w / im.width, h / im.height)
            im = im.resize((max(1, int(im.width * scale)), max(1, int(im.height * scale))), Image.LANCZOS)
            photo = ImageTk.PhotoImage(im)
        else:
            ext = os.path.splitext(path)[1].lower()
            if rot:
                # Без Pillow: поворот на любой угол через временный PPM + PhotoImage
                photo = self._tk_rotate_photo(path, w, h, rot, ext in NATIVE_TK_EXTS)
            elif ext in NATIVE_TK_EXTS:
                photo = tk.PhotoImage(file=path)
                iw, ih = photo.width(), photo.height()
                if iw > w or ih > h:
                    photo = photo.subsample(max(1, int(iw / max(1, w))), max(1, int(ih / max(1, h))))
            else:
                raise RuntimeError("Для JPG/JPEG/BMP/WEBP нужен Pillow")
        self.image_cache[key] = photo
        return photo

    # ---------- Поворот на 360° без Pillow (чистый Tk) ----------
    def _tmp_dir_get(self):
        if self._tmp_dir is None:
            self._tmp_dir = tempfile.mkdtemp(prefix="as_fox_eagle_manul_")
            atexit.register(self._tmp_dir_cleanup)
        return self._tmp_dir

    def _tmp_dir_cleanup(self):
        d = self._tmp_dir
        if d and os.path.isdir(d):
            shutil.rmtree(d, ignore_errors=True)
        self._tmp_dir = None

    def _photo_from_file_any(self, path):
        """Загружает PNG/GIF/PPM напрямую, прочие форматы конвертирует через Pillow (если он есть)."""
        try:
            return tk.PhotoImage(file=path)
        except tk.TclError:
            if not PIL_OK:
                raise
        im = Image.open(path)
        try:
            im = ImageOps.exif_transpose(im)
        except Exception:
            pass
        tmp_png = os.path.join(self._tmp_dir_get(), "conv_%d.png" % random.randint(0, 10**9))
        im.convert("RGBA").save(tmp_png)
        try:
            return tk.PhotoImage(file=tmp_png)
        finally:
            try:
                os.remove(tmp_png)
            except OSError:
                pass

    def _read_ppm_pixels(self, photo):
        tmp = os.path.join(self._tmp_dir_get(), "in_%d.ppm" % random.randint(0, 10**9))
        photo.write(tmp, format="ppm")
        try:
            with open(tmp, "rb") as f:
                raw = f.read()
        finally:
            try:
                os.remove(tmp)
            except OSError:
                pass
        # заголовок P6: magic, width, height, maxval — читаем все четыре поля
        idx, fields = 0, []
        while len(fields) < 4:
            while idx < len(raw) and raw[idx:idx + 1].isspace():
                idx += 1
            if idx >= len(raw):
                raise RuntimeError("Некорректный PPM")
            start = idx
            while idx < len(raw) and not raw[idx:idx + 1].isspace():
                idx += 1
            fields.append(raw[start:idx])
        idx += 1
        if fields[0] != b"P6":
            raise RuntimeError("Ожидался PPM P6")
        sw, sh = int(fields[1]), int(fields[2])
        return raw[idx:idx + sw * sh * 3], sw, sh

    def _src_pixels(self, path, box_w, box_h):
        """Пиксели исходника (PPM) с кэшем: дорогое чтение делается один раз на файл, а не на каждый кадр."""
        try:
            stamp = os.path.getmtime(path)
        except OSError:
            stamp = 0
        key = (path, stamp, int(box_w), int(box_h))
        cached = self._rot_px_cache.get(key)
        if cached is not None:
            return cached
        ext = os.path.splitext(path)[1].lower()
        photo = tk.PhotoImage(file=path) if ext in NATIVE_TK_EXTS else self._photo_from_file_any(path)
        # заранее уменьшаем исходник, чтобы поворот был быстрым
        k = max(1, min(photo.width() // (2 * int(box_w) + 1), photo.height() // (2 * int(box_h) + 1)))
        if k > 1:
            photo = photo.subsample(k)
        px, sw, sh = self._read_ppm_pixels(photo)
        if len(self._rot_px_cache) > 24:
            self._rot_px_cache.clear()
        self._rot_px_cache[key] = (px, sw, sh)
        return px, sw, sh

    def _tk_rotate_photo(self, path, box_w, box_h, rot, native=False):
        """Поворот картинки на произвольный угол средствами Tk: исходник -> PPM -> пиксели -> PPM -> PhotoImage."""
        px, sw, sh = self._src_pixels(path, box_w, box_h)

        rad = math.radians(rot % 360.0)
        c, s = math.cos(rad), math.sin(rad)
        rw = abs(sw * c) + abs(sh * s)
        rh = abs(sw * s) + abs(sh * c)
        scale = min(box_w / rw, box_h / rh)
        dw = max(1, int(round(rw * scale)))
        dh = max(1, int(round(rh * scale)))

        inv = 1.0 / scale
        cxd, cyd = dw / 2.0, dh / 2.0
        cxs, cys = sw / 2.0, sh / 2.0
        out = bytearray(dw * dh * 3)
        maxx, maxy = sw - 1, sh - 1
        o = 0
        for y in range(dh):
            dy = (y + 0.5 - cyd) * inv
            dx0 = (0.5 - cxd) * inv
            dxs = dy * s + cxs + dx0 * c
            dys = dy * c + cys - dx0 * s
            for x in range(dw):
                sx = int(dxs)
                sy = int(dys)
                if sx < 0:
                    sx = 0
                elif sx > maxx:
                    sx = maxx
                if sy < 0:
                    sy = 0
                elif sy > maxy:
                    sy = maxy
                si = (sy * sw + sx) * 3
                out[o] = px[si]
                out[o + 1] = px[si + 1]
                out[o + 2] = px[si + 2]
                o += 3
                dxs += c * inv
                dys -= s * inv

        tmp = os.path.join(self._tmp_dir_get(), "out_%d.ppm" % random.randint(0, 10**9))
        with open(tmp, "wb") as f:
            f.write(b"P6\n%d %d\n255\n" % (dw, dh))
            f.write(bytes(out))
        try:
            return tk.PhotoImage(file=tmp)
        finally:
            try:
                os.remove(tmp)
            except OSError:
                pass

    def _image_box_size(self, w, h, rot):
        """Габаритный прямоугольник картинки после поворота (чтобы ничего не обрезалось)."""
        rad = math.radians(self._parse_rot(rot) % 360.0)
        c, s = abs(math.cos(rad)), abs(math.sin(rad))
        return (int(round(w * c + h * s)), int(round(w * s + h * c)))


    def draw_image_or_poster(self, canvas, x, y, w, h, src, tag_group, rot=0):
        name = self._image_name(src)
        rot = self._parse_rot(rot)

        fpath = self._find_image_file(name)
        if fpath:
            try:
                photo = self._load_photo(fpath, w, h, rot)
                if not rot:
                    canvas.create_rectangle(x, y, x + w, y + h, fill="#000000", outline="#444", width=1, tags=tag_group)
                canvas.create_image(x + w / 2, y + h / 2, image=photo, tags=tag_group)
                if rot:
                    canvas.create_text(x + w - 4, y + h - 4, text=f"↻{rot}°", anchor="se", fill="#00897b", font=("Segoe UI", 8, "bold"), tags=tag_group)
                return
            except Exception:
                if not self._warned_pil and not PIL_OK:
                    self._warned_pil = True
                    try:
                        self.log("> [Картинки] Для JPG/JPEG/BMP/WEBP установите Pillow: pip install pillow (PNG/GIF и поворот работают и так).")
                    except Exception:
                        pass

        # Плакат-заглушка (файла картинки нет) — рисуем его повёрнутым
        c = _RotCanvasProxy(canvas, x + w / 2, y + h / 2, rot, tag_group) if rot else canvas

        if "inception" in name:
            c.create_rectangle(x, y, x + w, y + h, fill="#1b2a38", outline="#4fc3f7", width=2, tags=tag_group)
            c.create_rectangle(x + 10, y + 35, x + 38, y + h - 10, fill="#263849", outline="", tags=tag_group)
            c.create_rectangle(x + w - 38, y + 25, x + w - 10, y + h - 10, fill="#263849", outline="", tags=tag_group)
            c.create_line(x + w / 2, y + 60, x + w / 2, y + h - 15, fill="#ffcc80", width=2, dash=(4, 2), tags=tag_group)
            c.create_text(x + w / 2, y + 26, text="INCEPTION", fill="#ef5350", font=("Segoe UI", int(max(10, w * 0.09)), "bold"), tags=tag_group)
            c.create_text(x + w / 2, y + h / 2 + 10, text="🌀", font=("Segoe UI", int(max(22, w * 0.2))), tags=tag_group)
            c.create_text(x + w / 2, y + h - 22, text="inception.png", fill="#b0bec5", font=("Consolas", 8), tags=tag_group)
        elif "lotr" in name:
            c.create_rectangle(x, y, x + w, y + h, fill="#2b1b12", outline="#ffb300", width=2, tags=tag_group)
            c.create_oval(x + w / 2 - 36, y + h / 2 - 42, x + w / 2 + 36, y + h / 2 + 30, outline="#ffd54f", width=4, tags=tag_group)
            c.create_text(x + w / 2, y + 24, text="THE LORD OF\nTHE RINGS", fill="#ffe082", font=("Segoe UI", int(max(8, w * 0.065)), "bold"), justify=tk.CENTER, tags=tag_group)
            c.create_text(x + w / 2, y + h / 2 - 6, text="💍", font=("Segoe UI", int(max(20, w * 0.18))), tags=tag_group)
            c.create_text(x + w / 2, y + h - 22, text="lotr.png", fill="#d7ccc8", font=("Consolas", 8), tags=tag_group)
        elif "pirates" in name:
            c.create_rectangle(x, y, x + w, y + h, fill="#142229", outline="#80cbc4", width=2, tags=tag_group)
            c.create_text(x + w / 2, y + 26, text="PIRATES OF THE\nCARIBBEAN", fill="#b2dfdb", font=("Segoe UI", int(max(8, w * 0.065)), "bold"), justify=tk.CENTER, tags=tag_group)
            c.create_text(x + w / 2, y + h / 2 + 4, text="🏴‍☠️ ⚔️", font=("Segoe UI", int(max(20, w * 0.16))), tags=tag_group)
            c.create_text(x + w / 2, y + h - 22, text="pirates.png", fill="#b0bec5", font=("Consolas", 8), tags=tag_group)
        else:
            c.create_rectangle(x, y, x + w, y + h, fill="#E8F5E9", outline="#A5D6A7", width=2, tags=tag_group)
            cx = x + w / 2
            cy = y + h / 2 + 6
            r = min(w, h) * 0.28
            c.create_line(cx - r * 0.5, cy - r * 0.7, cx - r * 0.9, cy - r * 1.3, fill="#3DDC84", width=3, capstyle=tk.ROUND, tags=tag_group)
            c.create_line(cx + r * 0.5, cy - r * 0.7, cx + r * 0.9, cy - r * 1.3, fill="#3DDC84", width=3, capstyle=tk.ROUND, tags=tag_group)
            c.create_arc(cx - r, cy - r, cx + r, cy + r, start=0, extent=180, fill="#3DDC84", outline="#2E7D32", width=1.5, tags=tag_group)
            c.create_rectangle(cx - r, cy + 2, cx + r, cy + r * 1.15, fill="#3DDC84", outline="#2E7D32", width=1.5, tags=tag_group)
            eye_r = max(2, r * 0.11)
            c.create_oval(cx - r * 0.45 - eye_r, cy - r * 0.45 - eye_r, cx - r * 0.45 + eye_r, cy - r * 0.45 + eye_r, fill="white", outline="", tags=tag_group)
            c.create_oval(cx + r * 0.45 - eye_r, cy - r * 0.45 - eye_r, cx + r * 0.45 + eye_r, cy - r * 0.45 + eye_r, fill="white", outline="", tags=tag_group)
            c.create_text(cx, cy + r * 0.55, text="?", fill="#FFFFFF", font=("Segoe UI", int(max(12, r * 0.75)), "bold"), tags=tag_group)
        if rot:
            canvas.create_text(x + w - 4, y + h - 4, text=f"↻{rot}°", anchor="se", fill="#00897b", font=("Segoe UI", 8, "bold"), tags=tag_group)

    def draw_single_widget(self, canvas, w, group_tags, is_designer=True):
        x, y, width, height = w["x"], w["y"], w["w"], w["h"]
        tag = w["tag"]

        if tag == "Button":
            bg_c = w["bg"] if w["bg"] else "#0099FF"
            fg_c = w["fg"] if w["fg"] else "#FFFFFF"
            rot = self._parse_rot(w.get("rot", 0))
            if rot and PIL_OK:
                try:
                    cache_key = ("rot_button", bg_c, fg_c, w["text"], int(width), int(height),
                                 int(w.get("textSize", 15)), rot, w.get("font"), bool(w.get("bold")), bool(w.get("italic")))
                    photo = self.image_cache.get(cache_key)
                    if photo is None:
                        from PIL import ImageDraw, ImageFont
                        im = Image.new("RGBA", (max(1, int(width)), max(1, int(height))), bg_c)
                        draw = ImageDraw.Draw(im)
                        draw.rectangle((0, 0, int(width)-1, int(height)-1), outline="#0077CC", width=2)
                        try:
                            font = ImageFont.truetype(_pil_font_path(w), max(8, int(w["textSize"] * 0.75)))
                        except Exception:
                            try:
                                font = ImageFont.truetype("arial.ttf", max(8, int(w["textSize"] * 0.75)))
                            except Exception:
                                font = ImageFont.load_default()
                        text = str(w.get("text", ""))
                        box = draw.multiline_textbbox((0, 0), text, font=font, align="center")
                        tx = (width - (box[2] - box[0])) / 2
                        ty = (height - (box[3] - box[1])) / 2
                        draw.multiline_text((tx, ty), text, fill=fg_c, font=font, align="center")
                        im = im.rotate(-rot, expand=True, resample=Image.Resampling.BICUBIC)
                        photo = ImageTk.PhotoImage(im)
                        self.image_cache[cache_key] = photo
                    canvas.create_image(x + width / 2, y + height / 2, image=photo, tags=group_tags)
                except Exception:
                    canvas.create_rectangle(x, y, x + width, y + height, fill=bg_c, outline="#0077CC", width=1.5, tags=group_tags)
                    canvas.create_text(x + width / 2, y + height / 2, text=w["text"], fill=fg_c, angle=rot, font=_tk_font(w), width=width - 8, justify=tk.CENTER, tags=group_tags)
            else:
                canvas.create_rectangle(x, y, x + width, y + height, fill=bg_c, outline="#0077CC", width=1.5, tags=group_tags)
                canvas.create_text(x + width / 2, y + height / 2, text=w["text"], fill=fg_c, angle=rot, font=_tk_font(w), width=width - 8, justify=tk.CENTER, tags=group_tags)
            if is_designer and w.get("target_screen"):
                short_t = w["target_screen"].replace(".xml", "")
                canvas.create_rectangle(x + width - 78, y + 2, x + width - 2, y + 15, fill="#6A1B9A", outline="#FFD54F", width=1, tags=group_tags)
                canvas.create_text(x + width - 40, y + 8, text=f"➔ {short_t[:10]}", fill="#FFD54F", font=("Segoe UI", 7, "bold"), tags=group_tags)

        elif tag == "TextView":
            if w["bg"]:
                try:
                    canvas.create_rectangle(x, y, x + width, y + height, fill=w["bg"], outline="#d0d7de" if is_designer else "", tags=group_tags)
                except tk.TclError:
                    pass
            elif is_designer:
                canvas.create_rectangle(x, y, x + width, y + height, fill="", outline="#555" if self.root_bg.startswith("#1") else "#cfd8dc", dash=(3, 3), tags=group_tags)
            fg_c = w["fg"] if w["fg"] else "#212121"
            rot = self._parse_rot(w.get("rot", 0))
            try:
                canvas.create_text(x + width / 2, y + height / 2, text=w["text"], fill=fg_c, angle=rot,
                                   font=_tk_font(w), width=width - 6, justify=tk.CENTER, tags=group_tags)
            except tk.TclError:
                canvas.create_text(x + width / 2, y + height / 2, text=w["text"], fill="#212121", font=("Segoe UI", 11, "bold"), tags=group_tags)

        elif tag == "EditText":
            bg_c = w["bg"] if w["bg"] else "#FFFFFF"
            fg_c = w["fg"] if w["fg"] else "#212121"
            rot = self._parse_rot(w.get("rot", 0))
            canvas.create_rectangle(x, y, x + width, y + height, fill=bg_c, outline="#90A4AE", width=1.5, tags=group_tags)
            canvas.create_line(x + 4, y + height - 3, x + width - 4, y + height - 3, fill="#3574f0", width=2, tags=group_tags)
            canvas.create_text(x + 10, y + height / 2, text=w["text"], fill=fg_c, anchor="w", angle=rot,
                               font=_tk_font(w, scale=0.67), width=width - 16, tags=group_tags)

        elif tag == "Switch":
            fg_c = w["fg"] if w["fg"] else "#212121"
            rot = self._parse_rot(w.get("rot", 0))
            canvas.create_text(x + 8, y + height / 2, text=w["text"], fill=fg_c, anchor="w", angle=rot,
                               font=_tk_font(w, scale=0.67), tags=group_tags)
            sw_x = x + width - 46
            sw_y = y + height / 2 - 10
            is_on = w.get("checked", True)
            track_col = "#81C784" if is_on else "#B0BEC5"
            thumb_col = "#2E7D32" if is_on else "#ECEFF1"
            canvas.create_oval(sw_x, sw_y, sw_x + 38, sw_y + 20, fill=track_col, outline="", tags=group_tags)
            kx = sw_x + 20 if is_on else sw_x + 2
            canvas.create_oval(kx, sw_y + 2, kx + 16, sw_y + 18, fill=thumb_col, outline="white", tags=group_tags)

        elif tag == "ProgressBar":
            canvas.create_rectangle(x, y + height / 2 - 6, x + width, y + height / 2 + 6, fill="#E0E0E0", outline="#BDBDBD", tags=group_tags)
            canvas.create_rectangle(x, y + height / 2 - 6, x + int(width * 0.68), y + height / 2 + 6, fill="#3574f0", outline="", tags=group_tags)

        elif tag == "ImageView":
            self.draw_image_or_poster(canvas, x, y, width, height, w.get("src", "@drawable/android_question"), group_tags, w.get("rot", 0))

    def render_designer_canvas(self):
        self.design_canvas.delete("all")
        try:
            self.design_canvas.configure(bg=self.root_bg)
        except tk.TclError:
            self.design_canvas.configure(bg="#FFFFFF")

        for gx in range(0, self.canvas_w, 20):
            self.design_canvas.create_line(gx, 0, gx, self.canvas_h, fill="#262930" if self.root_bg.startswith("#1") else "#f0f2f5")
        for gy in range(0, self.canvas_h, 20):
            self.design_canvas.create_line(0, gy, self.canvas_w, gy, fill="#262930" if self.root_bg.startswith("#1") else "#f0f2f5")

        for w in self.widgets_data:
            wid = w["id"]
            x, y, width, height = w["x"], w["y"], w["w"], w["h"]
            is_sel = (wid == self.selected_id)
            group_tags = ("widget", wid)

            self.draw_single_widget(self.design_canvas, w, group_tags, is_designer=True)

            if is_sel:
                self.design_canvas.create_rectangle(x - 2, y - 2, x + width + 2, y + height + 2, outline="#3574f0", width=2)
                self.design_canvas.create_rectangle(
                    x + width - 6, y + height - 6, x + width + 6, y + height + 6,
                    fill="#3574f0", outline="white", width=1.5, tags=("resize_handle", wid)
                )
                if w["tag"] == "ImageView":
                    bx1, by1, bx2, by2 = self._dup_badge_rect(w)
                    self.design_canvas.create_rectangle(bx1, by1, bx2, by2, fill="#00897b", outline="white", width=1.5, tags=("dup_badge", wid))
                    self.design_canvas.create_text((bx1 + bx2) / 2, (by1 + by2) / 2, text="×2", fill="white", font=("Segoe UI", 9, "bold"), tags=("dup_badge", wid))
                if w["tag"] in ("ImageView", "Button", "TextView", "EditText", "Switch"):
                    hx, hy = self._rot_handle_pos(w)
                    self.design_canvas.create_line(x + width / 2, y + height / 2, hx, hy, fill="#3574f0", dash=(3, 3), width=1)
                    self.design_canvas.create_oval(hx - 7, hy - 7, hx + 7, hy + 7, fill="#3574f0", outline="white", width=1.5, tags=("rot_handle", wid))
                    self.design_canvas.create_text(hx, hy, text="↻", fill="white", font=("Segoe UI", 9, "bold"), tags=("rot_handle", wid))

    def _rot_handle_pos(self, w):
        """Позиция круглой ручки поворота: над элементом, на оси его текущего угла."""
        cx = w["x"] + w["w"] / 2.0
        cy = w["y"] + w["h"] / 2.0
        rad = math.radians(self._parse_rot(w.get("rot", 0)))
        r = math.hypot(w["w"], w["h"]) / 2.0 + 22
        return cx + r * math.sin(rad), cy - r * math.cos(rad)

    def get_widget_by_id(self, wid):
        for w in self.widgets_data:
            if w["id"] == wid:
                return w
        return None

    def find_free_position(self, w_width, w_height):
        candidate_x = 40
        candidate_y = 30
        while candidate_y + w_height < self.canvas_h - 10:
            overlap = False
            for existing in self.widgets_data:
                if abs(existing["y"] - candidate_y) < 38 and abs(existing["x"] - candidate_x) < 60:
                    overlap = True
                    break
            if not overlap:
                return candidate_x, candidate_y
            candidate_y += 50
        return 30 + (len(self.widgets_data) * 15) % 100, 40 + (len(self.widgets_data) * 35) % 350

    def add_new_widget(self, tag_type):
        existing_ids = {w["id"] for w in self.widgets_data}
        n = 1
        prefix_map = {
            "TextView": "tvText", "Button": "btnAction", "ImageView": "imgView",
            "EditText": "etInput", "Switch": "swToggle", "ProgressBar": "pbLoad"
        }
        prefix = prefix_map.get(tag_type, "widget")
        while f"{prefix}{n}" in existing_ids:
            n += 1
        new_id = f"{prefix}{n}"

        w_width = 220 if tag_type != "ImageView" else 110
        w_height = 44 if tag_type != "ImageView" else 110
        x, y = self.find_free_position(w_width, w_height)

        default_texts = {
            "TextView": f"Текст {n}",
            "Button": f"Кнопка {n}",
            "EditText": f"Введите текст {n}...",
            "Switch": f"Переключатель {n}",
            "ImageView": "",
            "ProgressBar": ""
        }

        new_w = {
            "tag": tag_type,
            "id": new_id,
            "text": default_texts.get(tag_type, ""),
            "x": x,
            "y": y,
            "w": w_width,
            "h": w_height,
            "textSize": 15,
            "bg": "#0099FF" if tag_type == "Button" else ("#FFFFFF" if tag_type == "EditText" else ""),
            "fg": "#FFFFFF" if tag_type == "Button" else "#212121",
            "src": "@drawable/android_question",
            "rot": 0,
            "checked": True,
            "bold": False,
            "italic": False,
            "font": "sans-serif",
        }
        self.widgets_data.append(new_w)
        self.select_widget(new_id)
        self.sync_model_to_xml()
        self.render_designer_canvas()
        self.log(f"> Добавлен {tag_type} с ID '@+id/{new_id}' на координаты ({x}dp, {y}dp).")

    # ---------- Оформление текста (жирный / курсив / шрифт) ----------
    def _font_android_from_label(self, label):
        for text, value in FONT_CHOICES:
            if text == label:
                return value
        return "sans-serif"

    def _font_label_from_android(self, value):
        for text, val in FONT_CHOICES:
            if val == value:
                return text
        return FONT_CHOICES[0][0]

    def _current_style_choice(self):
        """Что выбрано сейчас в инспекторе: (жирный, курсив, шрифт)."""
        if not hasattr(self, "prop_bold_var"):
            return False, False, "sans-serif"
        return (bool(self.prop_bold_var.get()),
                bool(self.prop_italic_var.get()),
                self._font_android_from_label(self.prop_font_var.get()))

    def update_text_preview(self):
        """Живой предпросмотр выбранного начертания и шрифта."""
        if not hasattr(self, "prop_preview_lbl"):
            return
        bold, italic, font = self._current_style_choice()
        base_size = 11
        sample = self.prop_text_var.get().strip() if hasattr(self, "prop_text_var") else ""
        w = self.get_widget_by_id(self.selected_id) if self.selected_id else None
        if w:
            try:
                base_size = max(9, min(18, int(w.get("textSize", 15) * 0.7)))
            except (TypeError, ValueError):
                base_size = 11
            if not sample and w["tag"] != "ImageView":
                sample = w["text"]
        if not sample:
            sample = "Предпросмотр текста"
        style = " ".join(p for p in ("bold" if bold else "", "italic" if italic else "") if p)
        self.prop_preview_lbl.config(
            text=sample[:60],
            font=(ANDROID_TO_TK_FONT.get(font, "Segoe UI"), base_size, style or "normal")
        )

    def _on_text_style_changed(self, event=None):
        self.update_text_preview()

    def apply_text_style_only(self):
        """Применяет только оформление текста, не трогая текст, цвет и положение."""
        w = self.get_widget_by_id(self.selected_id) if self.selected_id else None
        if not w:
            messagebox.showinfo("Оформление текста", "Сначала выберите элемент в дизайнере.", parent=self.root)
            return
        if w["tag"] == "ImageView":
            messagebox.showinfo("Оформление текста", "У картинки нет текста — оформление текста к ней не применяется.", parent=self.root)
            return
        bold, italic, font = self._current_style_choice()
        w["bold"], w["italic"], w["font"] = bold, italic, font
        self.sync_model_to_xml()
        self.render_designer_canvas()
        self.log(f"> Оформление '{w['id']}': шрифт {font}, жирный={'да' if bold else 'нет'}, курсив={'да' if italic else 'нет'}.")
        self.update_text_preview()

    def reset_text_style(self):
        """Сброс оформления к обычному начертанию и базовому шрифту."""
        w = self.get_widget_by_id(self.selected_id) if self.selected_id else None
        if not w:
            return
        w["bold"], w["italic"], w["font"] = False, False, "sans-serif"
        self.prop_bold_var.set(False)
        self.prop_italic_var.set(False)
        self.prop_font_var.set(FONT_CHOICES[0][0])
        self.sync_model_to_xml()
        self.render_designer_canvas()
        self.update_text_preview()
        self.log(f"> Оформление элемента '{w['id']}' сброшено к обычному шрифту.")

    def select_widget(self, wid):
        self.selected_id = wid
        w = self.get_widget_by_id(wid)
        self._rot_ui_syncing = True
        try:
            if w:
                self.prop_id_var.set(w["id"])
                self.prop_text_var.set(w["src"] if w["tag"] == "ImageView" else w["text"])
                self.prop_bg_var.set(w["bg"])
                self.prop_fg_var.set(w["fg"])
                self.prop_rot_var.set(str(w.get("rot", 0)))
                if hasattr(self, "prop_bold_var"):
                    self.prop_bold_var.set(bool(w.get("bold")))
                    self.prop_italic_var.set(bool(w.get("italic")))
                    self.prop_font_var.set(self._font_label_from_android(w.get("font", "sans-serif")))
                    is_text = w["tag"] != "ImageView"
                    state = tk.NORMAL if is_text else tk.DISABLED
                    self.prop_bold_chk.config(state=state)
                    self.prop_italic_chk.config(state=state)
                    self.prop_font_combo.config(state="readonly" if is_text else tk.DISABLED)
                if hasattr(self, "prop_rot_scale"):
                    self.prop_rot_scale.set(int(self._parse_rot(w.get("rot", 0))))
                if hasattr(self, "prop_target_var"):
                    self.prop_target_var.set(w.get("target_screen", ""))
            else:
                self.prop_id_var.set("")
                self.prop_text_var.set("")
                self.prop_bg_var.set("")
                self.prop_fg_var.set("")
                self.prop_rot_var.set("0")
                if hasattr(self, "prop_bold_var"):
                    self.prop_bold_var.set(False)
                    self.prop_italic_var.set(False)
                    self.prop_font_var.set(FONT_CHOICES[0][0])
                    self.prop_bold_chk.config(state=tk.NORMAL)
                    self.prop_italic_chk.config(state=tk.NORMAL)
                    self.prop_font_combo.config(state="readonly")
                if hasattr(self, "prop_rot_scale"):
                    self.prop_rot_scale.set(0)
                if hasattr(self, "prop_target_var"):
                    self.prop_target_var.set("")
        finally:
            self._rot_ui_syncing = False
        self.update_text_preview()

    def apply_inspector_props(self):
        if not self.selected_id:
            return
        w = self.get_widget_by_id(self.selected_id)
        if not w:
            return
        new_id = self.prop_id_var.get().strip()
        if new_id:
            w["id"] = new_id
            self.selected_id = new_id
        if w["tag"] == "ImageView":
            w["src"] = self.prop_text_var.get().strip()
        else:
            w["text"] = self.prop_text_var.get()
        w["rot"] = self._parse_rot(self.prop_rot_var.get())
        w["bg"] = self.prop_bg_var.get().strip()
        w["fg"] = self.prop_fg_var.get().strip()
        if w["tag"] != "ImageView" and hasattr(self, "prop_bold_var"):
            bold, italic, font = self._current_style_choice()
            w["bold"], w["italic"], w["font"] = bold, italic, font
        if hasattr(self, "prop_target_var"):
            target_scr = self.prop_target_var.get().strip()
            w["target_screen"] = target_scr
            if target_scr:
                self._inject_java_screen_navigation(w["id"], target_scr)

        self.sync_model_to_xml()
        self.render_designer_canvas()
        self.update_text_preview()
        self.log(f"> Свойства элемента '{w['id']}' обновлены.")

    def delete_selected_widget(self, event=None):
        if event is not None and self._focus_is_text_input():
            return None
        if event is not None and self.root.focus_get() is not self.design_canvas:
            return None
        if not self.selected_id:
            return "break" if event is not None else None
        deleted_id = self.selected_id
        self.widgets_data = [w for w in self.widgets_data if w["id"] != deleted_id]
        self.log(f"> Элемент '{deleted_id}' удален из макета и XML-кода.")
        self.select_widget(None)
        self.sync_model_to_xml()
        self.render_designer_canvas()
        return "break" if event is not None else None

    def _dup_badge_rect(self, w):
        x2 = w["x"] + w["w"]
        return (x2 - 30, w["y"] + 2, x2 - 2, w["y"] + 20)

    def _rects_overlap(self, ax, ay, aw, ah, bx, by, bw, bh):
        return ax < bx + bw - 1 and bx < ax + aw - 1 and ay < by + bh - 1 and by < ay + ah - 1

    def _find_aligned_slot(self, src):
        """Свободное место для копии: сетка с шагом (ширина+зазор, высота+зазор) от исходной картинки."""
        gap = 8
        w, h = int(src["w"]), int(src["h"])
        sx, sy = int(src["x"]), int(src["y"])
        cells = []
        for r in range(-40, 41):
            for c in range(-40, 41):
                x, y = sx + c * (w + gap), sy + r * (h + gap)
                if 0 <= x and x + w <= self.canvas_w and 0 <= y and y + h <= self.canvas_h:
                    cells.append((abs(r) + abs(c), r, c, x, y))
        # приоритет: справа, снизу, слева, сверху, затем ближайшие ячейки сетки
        cells.sort(key=lambda t: (t[0], 0 if (t[1] == 0 and t[2] > 0) else 1 if (t[2] == 0 and t[1] > 0) else 2, t[1], t[2]))
        for _, _, _, x, y in cells:
            if not any(self._rects_overlap(x, y, w, h, o["x"], o["y"], o["w"], o["h"]) for o in self.widgets_data):
                return x, y
        # экран заполнен — каскад со смещением (копировать можно бесконечно)
        k = sum(1 for o in self.widgets_data if o["tag"] == "ImageView")
        off = 12 * (k % 12 + 1)
        return (int(max(0, min(self.canvas_w - w, sx + off))), int(max(0, min(self.canvas_h - h, sy + off))))

    def duplicate_selected_image(self):
        src = self.get_widget_by_id(self.selected_id) if self.selected_id else None
        if not src or src["tag"] != "ImageView":
            images = [i for i in self.widgets_data if i["tag"] == "ImageView"]
            src = images[-1] if images else None
        if src is None:
            self.add_new_widget("ImageView")
            self.log("> [Удвоение] Картинок на экране не было — добавлена новая; нажмите ещё раз, чтобы удвоить.")
            return
        existing_ids = {i["id"] for i in self.widgets_data}
        base = re.sub(r'\d+$', '', src["id"]) or "imgView"
        n = 1
        while f"{base}{n}" in existing_ids:
            n += 1
        new_id = f"{base}{n}"

        clone = copy.deepcopy(src)
        clone["id"] = new_id
        clone["x"], clone["y"] = self._find_aligned_slot(src)
        self.widgets_data.append(clone)
        self.select_widget(new_id)
        self.sync_model_to_xml()
        self.render_designer_canvas()
        self.log(f"> [Удвоение] '{src['id']}' → '@+id/{new_id}' ({clone['w']}×{clone['h']}dp, поз. {clone['x']},{clone['y']}).")

    def rotate_selected_image(self, delta):
        w = self.get_widget_by_id(self.selected_id) if self.selected_id else None
        if not w or w["tag"] not in ("ImageView", "Button", "TextView", "EditText", "Switch"):
            messagebox.showinfo("Поворот", "Сначала выберите картинку или кнопку в дизайнере.", parent=self.root)
            return
        self._set_widget_rotation(w, self._parse_rot(w.get("rot", 0)) + delta)
        self.log(f"> Элемент '{w['id']}' повёрнут: {w['rot']}°.")

    def _set_widget_rotation(self, w, value, do_sync=True, do_render=True, do_note=False):
        """Единая точка изменения угла: модель + XML + холст + поле в Inspector."""
        w["rot"] = self._parse_rot(value)
        self._rot_ui_syncing = True
        try:
            if self.prop_rot_var.get() != str(w["rot"]):
                self.prop_rot_var.set(str(w["rot"]))
            if hasattr(self, "prop_rot_scale"):
                cur = int(self.prop_rot_scale.get())
                if cur != int(w["rot"]):
                    self.prop_rot_scale.set(int(w["rot"]))
        finally:
            self._rot_ui_syncing = False
        if do_sync:
            self.sync_model_to_xml()
        if do_render:
            self.render_designer_canvas()
        if do_note:
            self._history_note()

    def reset_selected_rotation(self):
        w = self.get_widget_by_id(self.selected_id) if self.selected_id else None
        if not w:
            messagebox.showinfo("Поворот", "Сначала выберите элемент в дизайнере.", parent=self.root)
            return
        self._set_widget_rotation(w, 0, do_note=True)
        self.log(f"> Угол элемента '{w['id']}' сброшен на 0°.")

    def ask_exact_rotation(self):
        w = self.get_widget_by_id(self.selected_id) if self.selected_id else None
        if not w:
            messagebox.showinfo("Поворот", "Сначала выберите элемент в дизайнере.", parent=self.root)
            return
        val = simpledialog.askstring(
            "Точный угол поворота",
            f"Введите угол для '{w['id']}' от 0 до 359.9 (по часовой стрелке):",
            initialvalue=str(w.get("rot", 0)), parent=self.root
        )
        if val is None:
            return
        self._set_widget_rotation(w, val, do_note=True)
        self.log(f"> Элемент '{w['id']}' повёрнут на {w['rot']}° (точный ввод).")

    def _on_rot_scale_changed(self, value):
        if self._rot_ui_syncing or not self.selected_id:
            return
        w = self.get_widget_by_id(self.selected_id)
        if not w or w["tag"] not in ("ImageView", "Button", "TextView", "EditText", "Switch"):
            return
        try:
            ang = float(value)
        except ValueError:
            return
        self._set_widget_rotation(w, ang)

    def _on_rot_slider_click(self, event):
        """Клик по жёлобу ползунка: сразу переходим на этот угол (иначе Tk сдвигает на 1°).
        Клик по самой ручке не перехватываем — её перетаскивание остаётся штатным."""
        sc = self.prop_rot_scale
        width = sc.winfo_width()
        half = int(sc.cget("sliderlength")) // 2
        usable = max(1, width - 2 * half)
        lo, hi = float(sc.cget("from")), float(sc.cget("to"))
        knob_x = half + (float(sc.get()) - lo) / max(1e-9, hi - lo) * usable
        if abs(event.x - knob_x) <= half + 2:
            return None  # попали по ручке — отдаём событие Tk
        frac = min(1.0, max(0.0, (event.x - half) / float(usable)))
        ang = int(round(lo + frac * (hi - lo)))
        sc.set(ang)
        self._on_rot_scale_changed(str(ang))
        return "break"

    def _on_rot_slider_released(self, event=None):
        self._history_note()

    def _on_rot_entry_changed(self, *_args):
        if self._rot_ui_syncing or not self.selected_id:
            return
        w = self.get_widget_by_id(self.selected_id)
        if not w or w["tag"] not in ("ImageView", "Button", "TextView", "EditText", "Switch"):
            return
        raw = self.prop_rot_var.get().strip()
        if not raw:
            return
        self._set_widget_rotation(w, raw)

    def _start_rotate_drag(self, mx, my, w):
        self.drag_mode = "rotate"
        self.drag_start_x = mx
        self.drag_start_y = my
        self.orig_rot = self._parse_rot(w.get("rot", 0))
        self._rot_center = (w["x"] + w["w"] / 2.0, w["y"] + w["h"] / 2.0)
        cx, cy = self._rot_center
        # запоминаем угол, под которым схватили ручку, чтобы картинка не прыгала
        self._rot_start_angle = math.degrees(math.atan2(mx - cx, -(my - cy)))

    def _on_rotate_motion(self, mx, my, shift=False):
        w = self.get_widget_by_id(self.selected_id)
        if not w:
            return
        cx, cy = self._rot_center
        ang = math.degrees(math.atan2(mx - cx, -(my - cy))) - self._rot_start_angle
        new_rot = self.orig_rot + ang
        if shift:
            new_rot = round(new_rot / 15.0) * 15.0  # Shift — шаг 15°
        self._set_widget_rotation(w, new_rot)

    def pick_image_file(self):
        w = self.get_widget_by_id(self.selected_id) if self.selected_id else None
        if not w or w["tag"] != "ImageView":
            self.add_new_widget("ImageView")
            w = self.get_widget_by_id(self.selected_id)
        path = filedialog.askopenfilename(
            title="Выберите картинку",
            filetypes=[("Изображения", " ".join("*" + e for e in IMAGE_EXTS)), ("Все файлы", "*.*")]
        )
        if not path:
            return
        name = re.sub(r"[^a-z0-9_]", "_", os.path.splitext(os.path.basename(path))[0].lower()) or "image"
        if name[0].isdigit():
            name = "img_" + name
        self.image_files[name] = path
        w["src"] = f"@drawable/{name}"
        self.prop_text_var.set(w["src"])
        if not PIL_OK and os.path.splitext(path)[1].lower() not in NATIVE_TK_EXTS:
            self.log("> [Картинки] Формат требует Pillow: pip install pillow (пока показан значок-заглушка).")
        self.sync_model_to_xml()
        self.render_designer_canvas()
        self.log(f"> Картинка '{os.path.basename(path)}' назначена элементу '{w['id']}' как {w['src']}.")

    def on_canvas_mouse_down(self, event):
        mx, my = event.x, event.y
        self._hist_drag_pushed = False
        self.design_canvas.focus_set()

        if self.selected_id:
            sel_w = self.get_widget_by_id(self.selected_id)
            if sel_w and sel_w["tag"] == "ImageView":
                bx1, by1, bx2, by2 = self._dup_badge_rect(sel_w)
                if bx1 <= mx <= bx2 and by1 <= my <= by2:
                    self.drag_mode = None
                    self._dup_click_time = datetime.datetime.now().timestamp()
                    self.duplicate_selected_image()
                    return
            if sel_w and sel_w["tag"] in ("ImageView", "Button", "TextView", "EditText", "Switch"):
                hx, hy = self._rot_handle_pos(sel_w)
                if math.hypot(mx - hx, my - hy) <= 12:
                    self._start_rotate_drag(mx, my, sel_w)
                    return
            if sel_w:
                hx, hy = sel_w["x"] + sel_w["w"], sel_w["y"] + sel_w["h"]
                if abs(mx - hx) <= 10 and abs(my - hy) <= 10:
                    self.drag_mode = "resize"
                    self.drag_start_x = mx
                    self.drag_start_y = my
                    self.orig_w = sel_w["w"]
                    self.orig_h = sel_w["h"]
                    return

        clicked_w = None
        for w in reversed(self.widgets_data):
            if w["x"] <= mx <= w["x"] + w["w"] and w["y"] <= my <= w["y"] + w["h"]:
                clicked_w = w
                break

        if clicked_w:
            self.select_widget(clicked_w["id"])
            self.drag_mode = "move"
            self.drag_start_x = mx
            self.drag_start_y = my
            self.orig_x = clicked_w["x"]
            self.orig_y = clicked_w["y"]
        else:
            self.select_widget(None)
            self.drag_mode = None

        self.render_designer_canvas()

    def on_canvas_mouse_drag(self, event):
        if not self.selected_id or not self.drag_mode:
            return
        w = self.get_widget_by_id(self.selected_id)
        if not w:
            return

        dx = event.x - self.drag_start_x
        dy = event.y - self.drag_start_y

        if self.drag_mode == "rotate":
            self._on_rotate_motion(event.x, event.y, bool(event.state & 0x0001))
            return

        if self.drag_mode == "move":
            new_x = max(0, min(self.canvas_w - w["w"], self.orig_x + dx))
            new_y = max(0, min(self.canvas_h - w["h"], self.orig_y + dy))
            w["x"] = int(new_x)
            w["y"] = int(new_y)
        elif self.drag_mode == "resize":
            new_w = max(40, min(self.canvas_w - w["x"], self.orig_w + dx))
            new_h = max(26, min(self.canvas_h - w["y"], self.orig_h + dy))
            w["w"] = int(new_w)
            w["h"] = int(new_h)

        self.render_designer_canvas()
        self.sync_model_to_xml()

    def on_canvas_mouse_up(self, event):
        was_rotate = self.drag_mode == "rotate"
        self.drag_mode = None
        if was_rotate and self.selected_id:
            w = self.get_widget_by_id(self.selected_id)
            if w:
                self.log(f"> Элемент '{w['id']}' повёрнут мышью: {w['rot']}°.")
                self._history_note()

    def on_canvas_wheel(self, event):
        """Колесо мыши над выбранным элементом — поворот шагом 5° (с Shift — 1°)."""
        if not self.selected_id:
            return None
        w = self.get_widget_by_id(self.selected_id)
        if not w or w["tag"] not in ("ImageView", "Button", "TextView", "EditText", "Switch"):
            return None
        mx, my = self.design_canvas.canvasx(event.x), self.design_canvas.canvasy(event.y)
        if not (w["x"] <= mx <= w["x"] + w["w"] and w["y"] <= my <= w["y"] + w["h"]):
            return None
        step = 1 if (event.state & 0x0001) else 5
        delta = getattr(event, "delta", 0)
        if delta == 0:
            delta = 120 if getattr(event, "num", 0) == 4 else -120
        self._set_widget_rotation(w, self._parse_rot(w.get("rot", 0)) + step * (1 if delta > 0 else -1), do_note=True)
        return "break"

    def on_canvas_double_click(self, event):
        if datetime.datetime.now().timestamp() - self._dup_click_time < 0.6:
            return
        if not self.selected_id:
            return
        w = self.get_widget_by_id(self.selected_id)
        if not w:
            return
        if w["tag"] == "ImageView":
            new_src = simpledialog.askstring(
                "Изменить картинку (src)",
                f"Укажите ресурс для '{w['id']}' (@drawable/inception, @drawable/lotr, @drawable/pirates):",
                initialvalue=w["src"],
                parent=self.root
            )
            if new_src is not None:
                w["src"] = new_src.strip()
                self.prop_text_var.set(w["src"])
                self.sync_model_to_xml()
                self.render_designer_canvas()
            return

        new_text = simpledialog.askstring(
            "Изменить текст",
            f"Введите новый текст для '{w['id']}':",
            initialvalue=w["text"],
            parent=self.root
        )
        if new_text is not None:
            w["text"] = new_text
            self.prop_text_var.set(new_text)
            self.sync_model_to_xml()
            self.render_designer_canvas()

    def generate_clean_constraintlayout_xml(self):
        lines = [
            '<?xml version="1.0" encoding="utf-8"?>',
            '<androidx.constraintlayout.widget.ConstraintLayout',
            '    xmlns:android="http://schemas.android.com/apk/res/android"',
            '    xmlns:app="http://schemas.android.com/apk/res-auto"',
            '    xmlns:tools="http://schemas.android.com/tools"',
            '    android:id="@+id/mainLayout"',
            '    android:layout_width="match_parent"',
            '    android:layout_height="match_parent"',
            f'    android:background="{self.root_bg}"',
            '    tools:context=".MainActivity">',
            ''
        ]
        for w in self.widgets_data:
            tag = w["tag"]
            lines.append(f'    <{tag}')
            lines.append(f'        android:id="@+id/{w["id"]}"')
            lines.append(f'        android:layout_width="{int(w["w"])}dp"')
            lines.append(f'        android:layout_height="{int(w["h"])}dp"')
            lines.append(f'        android:layout_marginStart="{int(w["x"])}dp"')
            lines.append(f'        android:layout_marginTop="{int(w["y"])}dp"')
            if tag not in ("ImageView", "ProgressBar"):
                escaped_text = w["text"].replace('"', '&quot;')
                lines.append(f'        android:text="{escaped_text}"')
                lines.append(f'        android:textSize="{w["textSize"]}sp"')
                if w["fg"]:
                    lines.append(f'        android:textColor="{w["fg"]}"')
                if w.get("bold") or w.get("italic"):
                    style_parts = [p for p in ("bold" if w.get("bold") else "", "italic" if w.get("italic") else "") if p]
                    lines.append(f'        android:textStyle="{"|".join(style_parts)}"')
                if w.get("font") and w.get("font") != "sans-serif":
                    lines.append(f'        android:fontFamily="{w["font"]}"')
                if w["bg"]:
                    attr_name = "backgroundTint" if tag == "Button" else "background"
                    lines.append(f'        android:{attr_name}="{w["bg"]}"')
            elif tag == "ImageView":
                lines.append(f'        android:src="{w["src"]}"')
            if w.get("rot"):
                lines.append(f'        android:rotation="{w["rot"]}"')
            lines.append('        app:layout_constraintStart_toStartOf="parent"')
            lines.append('        app:layout_constraintTop_toTopOf="parent" />')
            lines.append('')
        lines.append('</androidx.constraintlayout.widget.ConstraintLayout>')
        return "\n".join(lines)

    # ---------- Сохранение и загрузка проекта целиком (.avp) ----------
    PROJECT_EXT = ".avp"          # AndroidVybe Project
    PROJECT_FORMAT = 2

    def _project_payload(self):
        """Всё состояние работы: экраны, редакторы, тема, отметки заданий."""
        self.save_current_screen_state()
        return {
            "format": self.PROJECT_FORMAT,
            "app": "AndroidVybeIDE",
            "saved_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "current_screen": self.current_screen,
            "current_pr": self.current_pr_num,
            "project_topic": self.project_topic,
            "course_device": self.course_device,
            "root_bg": self.root_bg,
            "screens": copy.deepcopy(self.screens),
            "widgets": copy.deepcopy(self.widgets_data),
            "java": self.java_editor.get_code(),
            "manifest": self.manifest_editor.get_code(),
            "strings": self.strings_editor.get_code(),
            "image_files": {k: v for k, v in self.image_files.items()
                            if v and os.path.exists(v)},
            "pr_tasks_done": {str(k): sorted(v) for k, v in self.pr_tasks_done.items()},
        }

    def save_project_file(self, path=None):
        """Сохраняет текущую работу в один файл .avp, чтобы потом продолжить с того же места."""
        if not path:
            path = filedialog.asksaveasfilename(
                title="Сохранить проект AndroidVybeIDE",
                defaultextension=self.PROJECT_EXT,
                initialfile="Мой_проект" + self.PROJECT_EXT,
                filetypes=[("Проект AndroidVybeIDE", "*" + self.PROJECT_EXT), ("Все файлы", "*.*")],
                parent=self.root
            )
        if not path:
            return False
        payload = self._project_payload()
        try:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False, indent=1)
        except OSError as err:
            messagebox.showerror("Ошибка сохранения", f"Не удалось записать проект:\n{err}", parent=self.root)
            return False

        topic = TOPICS_BY_KEY.get(self.project_topic or "", None)
        self.log(f"> [Проект] Сохранён: {path}")
        messagebox.showinfo(
            "Проект сохранён",
            f"Проект сохранён в файл:\n{path}\n\n"
            f"Экранов: {len(self.screens)} · элементов на экране: {len(self.widgets_data)}\n"
            f"Тема: {topic['title'] if topic else 'не выбрана'}\n"
            f"Отметок по заданиям: {sum(len(v) for v in self.pr_tasks_done.values())}\n\n"
            f"Продолжить работу можно кнопкой «📂 Открыть проект».",
            parent=self.root
        )
        return True

    def open_project_file(self, path=None):
        """Загружает сохранённый проект и продолжает работу с того же места."""
        if not path:
            path = filedialog.askopenfilename(
                title="Открыть проект AndroidVybeIDE",
                filetypes=[("Проект AndroidVybeIDE", "*" + self.PROJECT_EXT), ("Все файлы", "*.*")],
                parent=self.root
            )
        if not path:
            return False
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError) as err:
            messagebox.showerror("Ошибка чтения",
                                 f"Не удалось прочитать проект:\n{err}\n\n"
                                 f"Убедитесь, что выбран файл {self.PROJECT_EXT} из этой программы.",
                                 parent=self.root)
            return False
        if not isinstance(data, dict) or "screens" not in data:
            messagebox.showerror("Ошибка формата",
                                 "Файл не похож на проект AndroidVybeIDE.\n"
                                 "Возможно, это экспорт .xml/.java, а не сохранённый проект.",
                                 parent=self.root)
            return False

        self._apply_project_payload(data, path)
        self.log(f"> [Проект] Открыт: {path}")
        topic = TOPICS_BY_KEY.get(self.project_topic or "", None)
        messagebox.showinfo(
            "Проект загружен",
            f"Загружен проект из файла:\n{path}\n\n"
            f"Сохранён: {data.get('saved_at', 'дата неизвестна')}\n"
            f"Экранов: {len(self.screens)} · тема: {topic['title'] if topic else 'не выбрана'}\n\n"
            f"Работа продолжена с того же места.",
            parent=self.root
        )
        return True

    def _apply_project_payload(self, data, path=None):
        """Применяет загруженные данные к интерфейсу, не теряя текущее состояние без нужды."""
        self.updating_from_code = True
        self.updating_from_canvas = True
        try:
            screens = data.get("screens") or {}
            self.screens = {str(k): {
                "xml": str(v.get("xml", "")),
                "bg": str(v.get("bg", "#FFFFFF")),
                "widgets": copy.deepcopy(v.get("widgets", [])),
            } for k, v in screens.items() if isinstance(v, dict)}
            if not self.screens:
                self.screens = {"activity_main.xml": {
                    "xml": str(data.get("xml", "")),
                    "bg": str(data.get("root_bg", "#FFFFFF")),
                    "widgets": copy.deepcopy(data.get("widgets", [])),
                }}

            cur = str(data.get("current_screen") or "")
            self.current_screen = cur if cur in self.screens else next(iter(self.screens))
            scr = self.screens[self.current_screen]

            self.java_editor.set_code(str(data.get("java", "")))
            self.manifest_editor.set_code(str(data.get("manifest", "")))
            self.strings_editor.set_code(str(data.get("strings", "")))

            self.project_topic = data.get("project_topic") or None
            dev = data.get("course_device")
            if dev in {k for k, _, _ in COURSE_DEVICES}:
                self.course_device = dev

            done_raw = data.get("pr_tasks_done") or {}
            self.pr_tasks_done = {}
            for k, v in done_raw.items():
                try:
                    self.pr_tasks_done[int(k)] = {int(i) for i in v}
                except (TypeError, ValueError):
                    continue

            imgs = data.get("image_files") or {}
            for name, img_path in imgs.items():
                if isinstance(img_path, str) and os.path.exists(img_path):
                    self.image_files[name] = img_path
            # Встроенная лиса могла быть во временной папке, удалённой при выходе — восстанавливаем
            uses_fox = any(
                w.get("src", "").endswith("fox_mascot")
                for scr in self.screens.values() for w in scr.get("widgets", [])
            )
            if uses_fox:
                fox_path = self._fox_mascot_file()
                if fox_path:
                    self.image_files["fox_mascot"] = fox_path

            self.root_bg = scr["bg"]
            self.xml_editor.set_code(scr["xml"])
            self.notebook.tab(0, text=f"📄 {self.current_screen}")
        finally:
            self.updating_from_code = False
            self.updating_from_canvas = False

        self.parse_xml_to_model()
        self.render_designer_canvas()
        self.refresh_screen_selectors()

        # Восстанавливаем выбранную ПР до обновления панели методички
        pr_num = data.get("current_pr")
        if isinstance(pr_num, int) and 0 <= pr_num <= 52:
            self.current_pr_num = pr_num
            for idx, item in enumerate(self.pr_list):
                if self.pr_num_from_key(item[0]) == pr_num:
                    self.pr_combo.current(idx)
                    break
        self.refresh_task_panel()
        self.refresh_topic_label()
        self._history_reset()

    def export_for_android_studio(self):
        parent_dir = filedialog.askdirectory(title="Выберите место, где будет создана ОТДЕЛЬНАЯ папка проекта (AS fox&eagle&manul)")
        if not parent_dir:
            return

        default_name = "PallasCat_Project_" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        folder_name = simpledialog.askstring(
            "Отдельная папка проекта",
            "Введите имя новой папки, в которую будут сохранены .xml и .java файлы:",
            initialvalue=default_name, parent=self.root
        )
        if folder_name is None:
            return
        folder_name = re.sub(r'[\\/:*?"<>|]', "_", folder_name).strip().strip(".") or default_name
        target_dir = os.path.join(parent_dir, folder_name)

        if os.path.isdir(target_dir) and os.listdir(target_dir):
            if not messagebox.askyesno("Папка уже существует", f"Папка '{folder_name}' не пуста. Сохранить файлы в неё (одноимённые будут перезаписаны)?", parent=self.root):
                return
        try:
            os.makedirs(target_dir, exist_ok=True)
        except OSError as err:
            messagebox.showerror("Ошибка", f"Не удалось создать папку:\n{err}", parent=self.root)
            return

        self.save_current_screen_state()
        clean_xml = self.generate_clean_constraintlayout_xml()
        java_code = self.java_editor.get_code()
        manifest_code = self.manifest_editor.get_code()
        strings_code = self.strings_editor.get_code()

        files = {}
        for scr_name, scr_data in self.screens.items():
            files[scr_name] = clean_xml if scr_name == self.current_screen else scr_data.get("xml", "")
        if self.current_screen not in files:
            files[self.current_screen] = clean_xml
        if "activity_main.xml" not in files:
            files["activity_main.xml"] = clean_xml
        files["MainActivity.java"] = java_code
        files["AndroidManifest.xml"] = manifest_code
        files["strings.xml"] = strings_code

        try:
            for fname, content in files.items():
                with open(os.path.join(target_dir, fname), "w", encoding="utf-8") as f:
                    f.write(content)
        except OSError as err:
            messagebox.showerror("Ошибка сохранения", f"Не удалось записать файлы:\n{err}", parent=self.root)
            return

        saved_list = "\n".join(f"  • {n}" for n in files)
        self.log(f"> [Экспорт] Сохранены только .xml и .java файлы в отдельную папку: {target_dir}")
        messagebox.showinfo(
            "AS fox&eagle&manul — Экспорт завершен",
            f"Файлы (.xml / .java) сохранены в отдельную папку:\n{target_dir}\n\n{saved_list}"
        )

    def _manul_local_file(self):
        if self.manul_custom_path and os.path.exists(self.manul_custom_path):
            return self.manul_custom_path
        for d in (SCRIPT_DIR, os.getcwd()):
            for nm in ("manul", "manul_photo", "pallas_cat", "pallascat", "pallas"):
                for ext in IMAGE_EXTS:
                    cand = os.path.join(d, nm + ext)
                    if os.path.exists(cand):
                        return cand
        return None

    def _download_manul(self):
        import urllib.request
        import json
        import tempfile
        ua = {"User-Agent": "ASPallasCat/1.1 (educational IDE; python-urllib)"}
        api = "https://en.wikipedia.org/api/rest_v1/page/summary/Pallas%27s_cat"
        data = json.loads(urllib.request.urlopen(urllib.request.Request(api, headers=ua), timeout=10).read().decode("utf-8"))
        src = (data.get("thumbnail") or {}).get("source") or (data.get("originalimage") or {}).get("source")
        if not src:
            raise RuntimeError("API не вернул адрес фото")
        candidates = [re.sub(r"/\d+px-", "/800px-", src), src]
        content = None
        for url in candidates:
            try:
                content = urllib.request.urlopen(urllib.request.Request(url, headers=ua), timeout=20).read()
                src = url
                break
            except Exception:
                continue
        if not content:
            raise RuntimeError("Не удалось скачать фото")
        ext = os.path.splitext(src.split("?")[0])[1].lower()
        ext = ext if ext in IMAGE_EXTS else ".jpg"
        for d in (SCRIPT_DIR, tempfile.gettempdir()):
            try:
                path = os.path.join(d, "manul" + ext)
                with open(path, "wb") as f:
                    f.write(content)
                return path
            except OSError:
                continue
        raise RuntimeError("Не удалось сохранить фото")

    def show_manul_photo(self, event=None):
        import threading
        win = getattr(self, "manul_win", None)
        try:
            if win is not None and win.winfo_exists():
                win.lift()
                return
        except tk.TclError:
            pass
        win = tk.Toplevel(self.root)
        self.manul_win = win
        win.title("Манул (кот Палласа) — AS fox&eagle&manul v1.0.3")
        win.configure(bg="#1e1f22")
        win.geometry("560x620")
        info = tk.Label(win, text="🐱 Загрузка фотографии манула…", bg="#1e1f22", fg="#ffca28", font=("Segoe UI", 11, "bold"))
        info.pack(pady=8)
        holder = tk.Label(win, bg="#1e1f22")
        holder.pack(expand=True, fill=tk.BOTH, padx=8)
        bar = tk.Frame(win, bg="#1e1f22")
        bar.pack(fill=tk.X, pady=6)

        def choose_own():
            p = filedialog.askopenfilename(title="Фото манула", filetypes=[("Изображения", " ".join("*" + e for e in IMAGE_EXTS)), ("Все файлы", "*.*")], parent=win)
            if p:
                self.manul_custom_path = p
                show(p, None)

        tk.Button(bar, text="📂 Выбрать своё фото манула…", bg="#4e5157", fg="white", bd=0, padx=8, pady=4, command=choose_own).pack(side=tk.LEFT, padx=8)
        tk.Button(bar, text="🌐 Страница в Википедии", bg="#4e5157", fg="white", bd=0, padx=8, pady=4,
                  command=lambda: __import__("webbrowser").open("https://ru.wikipedia.org/wiki/%D0%9C%D0%B0%D0%BD%D1%83%D0%BB")).pack(side=tk.LEFT, padx=4)

        result = {}

        def worker():
            try:
                preferred_candidates = [os.path.join(SCRIPT_DIR, n) for n in ("my_image.png", "my.png", "image.png", "manul.png")]
                preferred = next((p for p in preferred_candidates if os.path.exists(p)), None)
                result["path"] = self.manul_custom_path if self.manul_custom_path and os.path.exists(self.manul_custom_path) else (preferred if preferred else (self._manul_local_file() or self._download_manul()))
            except Exception as err:
                result["error"] = str(err)

        def show(path, error):
            try:
                if not win.winfo_exists():
                    return
            except tk.TclError:
                return
            if error or not path:
                info.config(text="Не удалось получить фото (нет интернета?). Положите manul.jpg рядом со скриптом\nили выберите своё фото кнопкой ниже.", fg="#ef9a9a")
                return
            try:
                if PIL_OK:
                    im = Image.open(path)
                    try:
                        im = ImageOps.exif_transpose(im)
                    except Exception:
                        pass
                    im = im.convert("RGB")
                    sc = min(540 / im.width, 500 / im.height)
                    im = im.resize((max(1, int(im.width * sc)), max(1, int(im.height * sc))), Image.LANCZOS)
                    photo = ImageTk.PhotoImage(im)
                elif os.path.splitext(path)[1].lower() in NATIVE_TK_EXTS:
                    photo = tk.PhotoImage(file=path)
                else:
                    raise RuntimeError("Для JPG установите Pillow: pip install pillow")
                holder.config(image=photo)
                holder.image = photo
                info.config(text="🐱 Манул (Otocolobus manul) — кот Палласа", fg="#ffca28")
            except Exception as err:
                info.config(text=f"Не удалось показать фото: {err}", fg="#ef9a9a")

        def poll():
            if "path" in result or "error" in result:
                show(result.get("path"), result.get("error"))
            else:
                win.after(150, poll)

        threading.Thread(target=worker, daemon=True).start()
        poll()

