    def start_build_process(self):
        self.parse_xml_to_model()
        self.save_current_screen_state()
        self.render_designer_canvas()
        self.log("\n> [AS fox&eagle&manul Build] Executing tasks: [:app:assembleDebug]...")
        self.log("> [Lifecycle ПР №24] D/ActivityLifecycle: onCreate() -> onStart() -> onResume()")

        build_win = tk.Toplevel(self.root)
        build_win.title("AS fox&eagle&manul — Сборка Gradle")
        build_win.geometry("440x155")
        build_win.transient(self.root)
        build_win.grab_set()
        build_win.configure(bg="#2b2d30")

        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 220
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 75
        build_win.geometry(f"+{x}+{y}")

        lbl = tk.Label(build_win, text="🐱 AS fox&eagle&manul: Сборка APK...", font=("Segoe UI", 11, "bold"), bg="#2b2d30", fg="white")
        lbl.pack(pady=20)

        progress = ttk.Progressbar(build_win, orient="horizontal", length=360, mode="determinate")
        progress.pack(pady=10)

        steps = 20

        def step_anim(s=0):
            if s <= steps:
                progress["value"] = (s / steps) * 100
                if s == 6:
                    lbl.config(text="Проверка AndroidManifest.xml и ресурсов...")
                elif s == 13:
                    lbl.config(text="Компиляция MainActivity.java...")
                elif s == 18:
                    lbl.config(text="Запуск эмулятора fox&eagle&manul Pixel 6...")
                self.root.after(40, step_anim, s + 1)
            else:
                self.log("> BUILD SUCCESSFUL in 1s. APK установлен на эмулятор.")
                build_win.destroy()
                self.launch_emulator()

        step_anim()

